(function(A){Object.assign(A.D,{"G1352":{"l":"διό","o":52,"ar":"<f><o>διό </o></f> <s>أداة ربط بمعنى <g>δι᾽ ὅ</g>، </s> <s><b>لذلك، لهذا السبب</b>: <r v=\"Matt.27.8\"></r>، <r v=\"Luke.7.7\"></r>، <r v=\"Acts.15.19\"></r>، <r v=\"Rom.1.24\"></r>، وفي مواضع أخرى؛ <g>δ. καί</g>: <r v=\"Luke.1.35\"></r>، <r v=\"Acts.10.29\"></r>، <r v=\"Acts.24.26\"></r>، <r v=\"Rom.4.22\"></r>، <r v=\"Rom.15.22\"></r>، <r v=\"2Cor.1.20\"></r>، <r v=\"2Cor.4.13\"></r>، <r v=\"2Cor.5.9\"></r>، <r v=\"Phil.2.9\"></r>، <r v=\"Heb.11.12\"></r>، <r v=\"Heb.13.12\"></r> (قارن <r v=\"Gal.4.31\"></r>).</s>","en":"<f><o>διό </o></f> <s>conjunct. for <g>δι᾽ ὅ</g>, </s> <s><b>wherefore, on which account</b>: <r v=\"Matt.27.8\"></r>, <r v=\"Luke.7.7\"></r>, <r v=\"Acts.15.19\"></r>, <r v=\"Rom.1.24\"></r>, al.; <g>δ. καί</g>, <r v=\"Luke.1.35\"></r>, <r v=\"Acts.10.29\"></r> <r v=\"Acts.24.26\"></r>, <r v=\"Rom.4.22\"></r> <r v=\"Rom.15.22\"></r>, <r v=\"2Cor.1.20\"></r> <r v=\"2Cor.4.13\"></r> <r v=\"2Cor.5.9\"></r>, <r v=\"Phil.2.9\"></r>, <r v=\"Heb.11.12\"></r> <r v=\"Heb.13.12\"></r> (v. Ellic. on <r v=\"Gal.4.31\"></r>).</s>"},"G1342":{"l":"δίκαιος","o":79,"ar":"<f><o>δίκαιος</o>، <g>-α, -ον</g></f> <s> <s n=\"(a)\">عن الأشخاص: المراعي لـ <g>δίκη</g>، أي العُرف والقاعدة والحق، <b>بارّ</b> في أداء واجباته نحو الآلهة والناس؛ </s> <s n=\"(b)\">عن الأشياء: <b>بارّ (عادل)</b>، موافق للحق. </s> </s> <s>في العهد الجديد <s n=\"1.\"><b>بارّ</b>، غالبًا بالمعنى الواسع المذكور أعلاه، عن الشخص أو الشيء المطابق لمقياس الحق الإلهي <s n=\"(a)\">عن الأشخاص: عن الله، <r v=\"Rom.3.26\"></r>، <r v=\"1John.2.29\"></r> <r v=\"1John.3.7\"></r>؛ عن المسيح، <r v=\"Acts.3.14\"></r> <r v=\"Acts.7.52\"></r> <r v=\"Acts.22.14\"></r>، <r v=\"1Pet.3.18\"></r>، <r v=\"1John.2.1\"></r>؛ عن البشر، <r v=\"Matt.1.19\"></r> <r v=\"Matt.10.41\"></r> <r v=\"Matt.13.17\"></r>، <r v=\"Matt.13.43\"></r>، <r v=\"Matt.13.49\"></r>، <r v=\"Luke.1.6\"></r>، <r v=\"Luke.1.17\"></r>، <r v=\"Rom.5.7\"></r>، <r v=\"1Tim.1.9\"></r>، <r v=\"Jas.5.6\"></r>، <r v=\"1Pet.3.12\"></r>، <r v=\"1John.3.7\"></r>، <r v=\"Rev.22.11\"></r>، وفي مواضع أخرى؛ <g>δ. καὶ εὐλαβής</g>، <r v=\"Luke.2.25\"></r>؛ <g>ἅγιος</g>، <r v=\"Mark.6.20\"></r>؛ <g>ἀγαθός</g>، <r v=\"Luke.23.50\"></r>؛ <g>φοβούμενος τ. θεόν</g>، <r v=\"Acts.10.22\"></r>؛ عكس <g>ἀμαρτωλοὶ καὶ ἀσεβεῖς</g>، <r v=\"1Pet.4.18\"></r>؛ <g>ἄδικοι</g>، <r v=\"Matt.5.45\"></r>، <r v=\"Acts.24.15\"></r>؛ <g>δ. ἐκ πίστεως</g>، <r v=\"Rom.1.17\"></r>، <r v=\"Gal.3.11\"></r>، <r v=\"Heb.10.38\"></r> <i>(السبعينية)</i>؛ <g>δ. παρὰ τ. θεῷ</g>، <r v=\"Rom.2.13\"></r> </s> <s n=\"(b)\">عن الأشياء: <g>ἔργα δ.</g>، عكس <g>πονηρὰ</g>، <r v=\"1John.3.12\"></r>؛ <g>ἐντολή</g>، <r v=\"Rom.7.12\"></r>؛ مجازيًا، <g>αἷμα</g>، <r v=\"Matt.23.35\"></r>؛ <g>τὸ δ.</g>، <r v=\"Luke.12.57\"></r>؛ <g>δ. ἐστιν</g>، <r v=\"Acts.4.19\"></r>، <r v=\"Eph.6.1\"></r>، <r v=\"Phil.1.7\"></r>؛ <g>ὅ</g>، <r v=\"Matt.20.4\"></r>؛ <g>ὅσα</g>، <r v=\"Phil.4.8\"></r> </s> </s> <s n=\"2.\">بمعنى أضيق <s n=\"(a)\">عن الأشخاص: <b>عادل</b>، يعطي كل واحد حقه: <r v=\"Titus.1.8\"></r>، <r v=\"1John.1.9\"></r>؛ <g>δ. κριτής</g>، <r v=\"2Tim.4.8\"></r> </s> <s n=\"(b)\">عن الأشياء: <g>τὸ δ.</g>، <r v=\"Col.4.1\"></r>؛ <g>δ.</g>، والمقصود <g>ἐστιν</g>، <r v=\"2Thess.1.6\"></r>؛ <g>κρίσις δ.</g>، <r v=\"John.5.30\"></r>؛ <g>ὁδοί</g>، <r v=\"Rev.15.3\"></r> </s> </s> </s>","en":"<f><o>δίκαιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δίκη</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6662\">צַדִּיק</h> (for rendering of <h n=\"H6662\">צַדִּיק</h> in sense of <b>correct</b>, v. Deiss., <i>BS</i>, 115 f.); sometimes for <h n=\"H5355\">נָקִי</h> as <r v=\"Prov.1.11\"></r>, al. ;] </e> </et> <s>in early Gk. writers <s n=\"(a)\">of persons, observant of <g>δίκη</g>, custom, rule, right, <b>righteous</b> in performing duties to gods and men ; </s> <s n=\"(b)\">of things, <b>righteous</b>, in accordance with right. </s> </s> <s>In NT <s n=\"1.\"><b>righteous</b>, chiefly in the broad sense, as above, of the person or thing corresponding to the Divine standard of right <s n=\"(a)\">of persons: of God, <r v=\"Rom.3.26\"></r>, <r v=\"1John.2.29\"></r> <r v=\"1John.3.7\"></r>; of Christ, <r v=\"Acts.3.14\"></r> <r v=\"Acts.7.52\"></r> <r v=\"Acts.22.14\"></r>, <r v=\"1Pet.3.18\"></r>, <r v=\"1John.2.1\"></r>; of men, <r v=\"Matt.1.19\"></r> (Abbott, <i>Essays</i>, 75 f.) <r v=\"Matt.10.41\"></r> <r v=\"Matt.13.17\"></r>, <r v=\"Matt.13.43\"></r>, <r v=\"Matt.13.49\"></r>, <r v=\"Luke.1.6\"></r>, <r v=\"Luke.1.17\"></r>, <r v=\"Rom.5.7\"></r>, <r v=\"1Tim.1.9\"></r>, <r v=\"Jas.5.6\"></r>, <r v=\"1Pet.3.12\"></r>, <r v=\"1John.3.7\"></r>, <r v=\"Rev.22.11\"></r>, al.; <g>δ. καὶ εὐλαβής</g>, <r v=\"Luke.2.25\"></r>; <g>ἅγιος</g>, <r v=\"Mark.6.20\"></r>; <g>ἀγαθός</g>, <r v=\"Luke.23.50\"></r>; <g>φοβούμενος τ. θεόν</g>, <r v=\"Acts.10.22\"></r>; opp. to <g>ἀμαρτωλοὶ καὶ ἀσεβεῖς</g>, <r v=\"1Pet.4.18\"></r>; <g>ἄδικοι</g>, <r v=\"Matt.5.45\"></r>, <r v=\"Acts.24.15\"></r>; <g>δ. ἐκ πίστεως</g>, <r v=\"Rom.1.17\"></r>, <r v=\"Gal.3.11\"></r>, <r v=\"Heb.10.38\"></r> <i>(LXX)</i>; <g>δ. παρὰ τ. θεῷ</g>, <r v=\"Rom.2.13\"></r> </s> <s n=\"(b)\">of things: <g>ἔργα δ.</g>, opp. to <g>πονηρὰ</g>, <r v=\"1John.3.12\"></r>; <g>ἐντολή</g>, <r v=\"Rom.7.12\"></r>; metaph., <g>αἷμα</g>, <r v=\"Matt.23.35\"></r>; <g>τὸ δ.</g>, <r v=\"Luke.12.57\"></r>; <g>δ. ἐστιν</g>, <r v=\"Acts.4.19\"></r>, <r v=\"Eph.6.1\"></r>, <r v=\"Phil.1.7\"></r>; <g>ὅ</g>, <r v=\"Matt.20.4\"></r>; <g>ὅσα</g>, <r v=\"Phil.4.8\"></r> </s> </s> <s n=\"2.\">In narrower sense <s n=\"(a)\">of persons, as in later cl. writers, <b>just</b>, rendering to each his due: <r v=\"Titus.1.8\"></r>, <r v=\"1John.1.9\"></r>; <g>δ. κριτής</g>, <r v=\"2Tim.4.8\"></r> </s> <s n=\"(b)\">of things: <g>τὸ δ.</g>, <r v=\"Col.4.1\"></r>; <g>δ.</g>, sc. <g>ἐστιν</g>, <r v=\"2Thess.1.6\"></r>; <g>κρίσις δ.</g>, <r v=\"John.5.30\"></r>; <g>ὁδοί</g>, <r v=\"Rev.15.3\"></r> </s> </s> </s> <sy><i>SYN.</i>: <g>ἀγαθός</g> (q.v.), <g>καλός</g>, <g>χρηστός</g> (Cremer, 183, 690).</sy>"},"G1381":{"l":"δοκιμάζω","o":22,"ar":"<f><o>δοκιμάζω</o></f> <s n=\"1.\">أصلاً عن المعادن (<r v=\"Prov.8.10\"></r> <r v=\"Prov.17.3\"></r>، <r v=\"Sir.2.5\"></r>، <r v=\"Wis.3.6\"></r>)، <b>يفحص، يمتحن، يختبر</b> (على رجاء وتوقُّع أن ينجح الامتحان): <g>χρυσίον</g>، <r v=\"1Pet.1.7\"></r>؛ أشياء أخرى، <r v=\"Luke.12.56\"></r> <r v=\"Luke.14.19\"></r>، <r v=\"2Cor.8.8\"></r>، <r v=\"Gal.6.4\"></r>، <r v=\"1Thess.2.4\"></r> <r v=\"1Thess.5.21\"></r>؛ <g>τὰ διαφέροντα</g>، <r v=\"Rom.2.18\"></r>، <r v=\"Phil.1.10\"></r>؛ <g>πνεύματα</g>، <r v=\"1John.4.1\"></r>؛ عن البشر، <r v=\"1Tim.3.10\"></r> (مبني للمجهول)؛ <g>ἑαυτόν</g>، <r v=\"1Cor.11.28\"></r>، <r v=\"2Cor.13.5\"></r>؛ يليه جملة اسمية (بمعنى المفعول)، <r v=\"Rom.12.2\"></r>، <r v=\"1Cor.3.13\"></r>، <r v=\"Eph.5.10\"></r>. </s> <s n=\"2.\">نتيجةً للامتحان، <b>يستحسن، يرى مناسبًا</b>: <r v=\"Rom.1.28\"></r> <r v=\"Rom.14.22\"></r>، <r v=\"1Cor.16.3\"></r>، <r v=\"2Cor.8.22\"></r>، <r v=\"1Thess.2.4\"></r> (<g>δεδοκιμάσμεθα</g>)؛ <g>τὰ διαφέροντα</g>، <r v=\"Rom.2.18\"></r>، <r v=\"Phil.1.10\"></r>.†</s>","en":"<f><o>δοκιμάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δόκιμος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H974\">בּחן</h> ;] </e> </et> <s n=\"1.\">primarily of metals (<r v=\"Prov.8.10\"></r> <r v=\"Prov.17.3\"></r>, <r v=\"Sir.2.5\"></r>, <r v=\"Wis.3.6\"></r>), <b>to test, try, prove</b> (in the hope and expectation that the test will prove successful, v. reff. s. <i>Syn.</i>): <g>χρυσίον</g>, <r v=\"1Pet.1.7\"></r>; other things, <r v=\"Luke.12.56\"></r> <r v=\"Luke.14.19\"></r>, <r v=\"2Cor.8.8\"></r>, <r v=\"Gal.6.4\"></r>, <r v=\"1Thess.2.4\"></r> <r v=\"1Thess.5.21\"></r>; <g>τὰ διαφέροντα</g>, <r v=\"Rom.2.18\"></r>, <r v=\"Phil.1.10\"></r> (R, mg., but v. infr.); <g>πνεύματα</g>, <r v=\"1John.4.1\"></r>; of men, <r v=\"1Tim.3.10\"></r> (pass.); <g>ἑαυτόν</g>, <r v=\"1Cor.11.28\"></r>, <r v=\"2Cor.13.5\"></r>; seq. subst. clause, <r v=\"Rom.12.2\"></r>, <r v=\"1Cor.3.13\"></r>, <r v=\"Eph.5.10\"></r>. </s> <s n=\"2.\">As the result of trial, <b>to approve, think fit</b>: <r v=\"Rom.1.28\"></r> <r v=\"Rom.14.22\"></r>, <r v=\"1Cor.16.3\"></r>, <r v=\"2Cor.8.22\"></r>, <r v=\"1Thess.2.4\"></r> (<g>δεδοκιμάσμεθα</g>); <g>τὰ διαφέροντα</g>, <r v=\"Rom.2.18\"></r>, <r v=\"Phil.1.10\"></r>, R, txt. (but v. supr.; cf. <g>διαφέρω</g>).†</s> <sy><i>SYN.</i>: <g>πειράζω</g> (v. Tr., <i>Syn.</i>, lxxiv; Cremer, 494 ff., 699 ff.).</sy>"},"G1398":{"l":"δουλεύω","o":26,"ar":"<f><o>δουλεύω</o></f> <s><b>يكون عبدًا، يخضع لـ، يخدم (يتعبّد)</b>: مطلقًا، <r v=\"Rom.7.6\"></r>، <r v=\"Gal.4.25\"></r>، <r v=\"1Tim.6.2\"></r>؛ مع قابل الشخص، <r v=\"Matt.6.24\"></r>، <r v=\"Luke.15.29\"></r> <r v=\"Luke.16.13\"></r>، <r v=\"Rom.9.12\"></r> <i>(السبعينية)</i>؛ عن الأمم، <r v=\"John.8.33\"></r>، <r v=\"Acts.7.7\"></r> <i>(السبعينية)</i>؛ <g>θεῷ, τ. κυρίῳ</g>، <r v=\"Matt.6.24\"></r>، <r v=\"Luke.16.13\"></r>، <r v=\"Acts.20.19\"></r>، <r v=\"Rom.12.11\"></r> <r v=\"Rom.16.18\"></r>، <r v=\"Eph.6.7\"></r>، <r v=\"Col.3.24\"></r>، <r v=\"1Thess.1.9\"></r>؛ <g>τ. Χριστῷ</g>، <r v=\"Rom.14.18\"></r>، <r v=\"Col.3.24\"></r>؛ <g>νόμῳ θεοῦ</g>، <r v=\"Rom.7.25\"></r>؛ <g>τ. θεοῖς</g>، <r v=\"Gal.4.8\"></r>؛ <g>τ. καιρῷ</g>، <r v=\"Rom.12.11\"></r>؛ <g>ἀλλήλοις</g>، <r v=\"Gal.5.13\"></r>؛ <g>σὺν ἐμοί</g> <r v=\"Phil.2.22\"></r>؛ <g>τ. ἁμαρτίᾳ</g>، <r v=\"Rom.6.6\"></r>؛ <g>νόμῳ ἁμαρτίας</g>، <r v=\"Rom.7.25\"></r>؛ <g>ἐπιθυμίαις κ. ἡδοναις</g>، <r v=\"Titus.3.3\"></r>؛ <g>τ. κοιλία</g>، <r v=\"Rom.16.18\"></r>؛ <g>μαμωνᾷ</g>، <r v=\"Matt.6.24\"></r>، <r v=\"Luke.16.13\"></r>؛ <g>τ. στοιχείοις τ, κόσμου</g>، <r v=\"Gal.4.9\"></r>.†</s>","en":"<f><o>δουλεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>δοῦλος</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5647\">עבד</h>, as <r v=\"Gen.14.4\"></r>, exc. <r v=\"Dan.7.14\"></r>, <r v=\"Dan.7.27\"></r> (<h n=\"H6399\">פְּלַח</h>), <r v=\"Isa.56.6\"></r> (<h n=\"H8334\">שׁרת</h> pi.)* ;]</e> </et> <s><b>to be a slave, be subject to, serve</b>: absol., <r v=\"Rom.7.6\"></r>, <r v=\"Gal.4.25\"></r>, <r v=\"1Tim.6.2\"></r>; c. dat pers., <r v=\"Matt.6.24\"></r>, <r v=\"Luke.15.29\"></r> <r v=\"Luke.16.13\"></r>, <r v=\"Rom.9.12\"></r> <i>(LXX)</i>; of nations, <r v=\"John.8.33\"></r>, <r v=\"Acts.7.7\"></r> <i>(LXX)</i>; <g>θεῷ, τ. κυρίῳ</g>, <r v=\"Matt.6.24\"></r>, <r v=\"Luke.16.13\"></r>, <r v=\"Acts.20.19\"></r>, <r v=\"Rom.12.11\"></r> (R, mg., <g>καιρῷ</g>) <r v=\"Rom.16.18\"></r>, <r v=\"Eph.6.7\"></r>, <r v=\"Col.3.24\"></r>, <r v=\"1Thess.1.9\"></r>; <g>τ. Χριστῷ</g>, <r v=\"Rom.14.18\"></r>, <r v=\"Col.3.24\"></r>; <g>νόμῳ θεοῦ</g>, <r v=\"Rom.7.25\"></r>; <g>τ. θεοῖς</g>, <r v=\"Gal.4.8\"></r>; <g>τ. καιρῷ</g>, <r v=\"Rom.12.11\"></r> (R, mg. for <g>κυρίῳ</g>); <g>ἀλλήλοις</g>, <r v=\"Gal.5.13\"></r>; <g>σὺν ἐμοί</g> <r v=\"Phil.2.22\"></r>; <g>τ. ἁμαρτίᾳ</g>, <r v=\"Rom.6.6\"></r>; <g>νόμῳ ἁμαρτίας</g>, <r v=\"Rom.7.25\"></r>; <g>ἐπιθυμίαις κ. ἡδοναις</g>, <r v=\"Titus.3.3\"></r>; <g>τ. κοιλία</g>, <r v=\"Rom.16.18\"></r>; <g>μαμωνᾷ</g>, <r v=\"Matt.6.24\"></r>, <r v=\"Luke.16.13\"></r>; <g>τ. στοιχείοις τ, κόσμου</g>, <r v=\"Gal.4.9\"></r> (Cremer, 217).†</s>"},"G1390":{"l":"δόμα","o":11,"ar":"<f><o>δόμα</o>، <g>-τος, τό</g></f> <s><b>عطية</b>: <r v=\"Matt.7.11\"></r>، <r v=\"Luke.11.13\"></r>، <r v=\"Eph.4.8\"></r> <i>(السبعينية)</i>، <r v=\"Phil.4.17\"></r>.†</s>","en":"<f><o>δόμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>δίδωμι</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4979\">מַתָּנָה</h>, etc. ;] </e> </et> <s><b>a gift</b>: <r v=\"Matt.7.11\"></r>, <r v=\"Luke.11.13\"></r>, <r v=\"Eph.4.8\"></r> <i>(LXX)</i>, <r v=\"Phil.4.17\"></r>.†</s> <sy><i>SYN.</i>: <g>δόσις</g>, <g>δῶρον</g>, <g>δωρεά</g>, <g>δώρημα</g>. </sy>"},"G1391":{"l":"δόξα","o":166,"ar":"<f><o>δόξα</o>، <g>-ης, ἡ</g> </f> <s><s n=\"1.\">في اليونانية الكلاسيكية: <b>توقُّع، حكم، رأي</b> (<r v=\"4Macc.5.18\"></r>). </s> <s n=\"2.\"><b>الرأي، التقدير</b> الذي يُنظر به إلى المرء، <b>السمعة</b>؛ وفي العهد الجديد دائمًا <b>الرأي الحسن</b>، ومن ثمّ <b>الصيت الحسن، المديح، الكرامة، المجد</b>: <r v=\"Luke.14.10\"></r>، <r v=\"John.12.43\"></r>، <r v=\"Heb.3.3\"></r>؛ عكس <g>αἰσχύνη</g>، <r v=\"Phil.3.19\"></r>؛ وعكس <g>ἀτιμία</g>، <r v=\"2Cor.6.8\"></r>؛ <g>δ. κ. τιμή</g>، <r v=\"Rom.2.7\"></r>، <r v=\"Rom.2.10\"></r>، <r v=\"1Pet.1.7\"></r>، <r v=\"2Pet.1.17\"></r>؛ <g>ζητεῖν</g>، <r v=\"John.5.44\"></r> <r v=\"John.7.18\"></r> <r v=\"John.8.50\"></r>، <r v=\"1Thess.2.6\"></r>؛ <g>λαμβάνειν</g>، <r v=\"John.5.41\"></r>، <r v=\"2Pet.1.17\"></r>، <r v=\"Rev.5.12\"></r>؛ <g>διδόναι δ. τ. θεῷ</g> (قارن <h n=\"H5414\">נָתַן כָּבוֹד לַיהוָֹה</h>، <r v=\"Jer.13.16\"></r>، وفي مواضع أخرى)، <r v=\"Luke.17.18\"></r>، <r v=\"John.9.24\"></r>، <r v=\"Acts.12.23\"></r>، <r v=\"Rom.4.20\"></r>، <r v=\"Rev.4.9\"></r>؛ <g>εἰς (τ.) δ. θεοῦ</g>، <r v=\"Rom.3.7\"></r> <r v=\"Rom.15.7\"></r>، <r v=\"Phil.1.11\"></r>، وفي مواضع أخرى؛ في التمجيدات، <g>τ. θεῷ (ᾧ) ἡ δ.</g>، <r v=\"Luke.2.14\"></r>، <r v=\"Rom.11.36\"></r> <r v=\"Rom.16.27\"></r>، <r v=\"Gal.1.5\"></r>، <r v=\"Eph.3.21\"></r>، وفي مواضع أخرى. </s> <s n=\"3.\">كما في السبعينية (= <h n=\"H1935\">הוֹד</h>، <r v=\"Job.39.20\"></r>، <r v=\"1Chr.29.25\"></r>؛ <h n=\"H3519\">כָּבֹוד</h>، <r v=\"Job.19.9\"></r>، <r v=\"Esth.5.11\"></r>، وفي مواضع أخرى): <b>لمعان، بهاء، مجد</b> منظور: عن النور، <r v=\"Acts.22.11\"></r>؛ عن الأجرام السماوية، <r v=\"1Cor.15.40\"></r><i> وما يليه </i>؛ خاصةً ذلك الذي يشع من حضرة الله، كما ظهر في عمود السحاب وفي قدس الأقداس (= <h n=\"H3519\">כָּבוֹד</h>، <r v=\"Exod.16.10\"></r> <r v=\"Exod.25.22\"></r> <r v=\"Exod.40.34\"></r>، وفي مواضع أخرى؛ والعبرية المتأخرة <h n=\"H7914\">שְׁכִינָה</h>، <r v=\"2Macc.2.8\"></r>)، <r v=\"Rom.9.4\"></r>، <r v=\"Jas.2.1\"></r>؛ ومن ثمّ عن مجد الله المُعلَن، <r v=\"Rom.1.23\"></r>، <r v=\"Col.1.11\"></r> <r v=\"Eph.1.6\"></r>، <r v=\"Eph.1.12\"></r>، <r v=\"Eph.1.17\"></r> <r v=\"Eph.3.16\"></r>؛ وعن المجد نفسه موهوبًا للإنسان بالمسيح، <r v=\"2Cor.3.18\"></r> <r v=\"2Cor.4.6\"></r>؛ وعن الحالة المجيدة التي سيدخلها المسيحيون فيما بعد، <r v=\"Rom.8.18\"></r>، <r v=\"Rom.8.21\"></r> <r v=\"Rom.9.23\"></r>، <r v=\"2Tim.2.10\"></r>، وفي مواضع أخرى. </s> </s>","en":"<f><o>δόξα</o>, <g>-ης, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>δοκέω</g>), </e> <e t=\"septuagint\">[in LXX very freq. for <h n=\"H3519\">כָּבוֹד</h>, also for <h n=\"H1935,H8597\">הוֹד ,תִּפְאֶרֶת</h>, etc., 25 words in all ;]</e> </et> <s>in cl., <s n=\"1.\"><b>expectation, judgment, opinion</b> (<r v=\"4Macc.5.18\"></r>). </s> <s n=\"2.\"><b>opinion, estimation</b> in which one is held, <b>repute</b>; in NT, always <b>good opinion</b>, hence <b>reputation, praise, honour, glory</b>: <r v=\"Luke.14.10\"></r>, <r v=\"John.12.43\"></r>, <r v=\"Heb.3.3\"></r>; opp. to <g>αἰσχύνη</g>, <r v=\"Phil.3.19\"></r>; to <g>ἀτιμία</g>, <r v=\"2Cor.6.8\"></r>; <g>δ. κ. τιμή</g>, <r v=\"Rom.2.7\"></r>, <r v=\"Rom.2.10\"></r>, <r v=\"1Pet.1.7\"></r>, <r v=\"2Pet.1.17\"></r>; <g>ζητεῖν</g>, <r v=\"John.5.44\"></r> <r v=\"John.7.18\"></r> <r v=\"John.8.50\"></r>, <r v=\"1Thess.2.6\"></r>; <g>λαμβάνειν</g>, <r v=\"John.5.41\"></r>, <r v=\"2Pet.1.17\"></r>, <r v=\"Rev.5.12\"></r>; <g>διδόναι δ. τ. θεῷ</g> (cf. <h n=\"H5414\">נָתַן כָּבוֹד לַיהוָֹה</h>, <r v=\"Jer.13.16\"></r>, al.), <r v=\"Luke.17.18\"></r>, <r v=\"John.9.24\"></r>, <r v=\"Acts.12.23\"></r>, <r v=\"Rom.4.20\"></r>, <r v=\"Rev.4.9\"></r>; <g>εἰς (τ.) δ. θεοῦ</g>, <r v=\"Rom.3.7\"></r> <r v=\"Rom.15.7\"></r>, <r v=\"Phil.1.11\"></r>, al.; in doxologies, <g>τ. θεῷ (ᾧ) ἡ δ.</g>, <r v=\"Luke.2.14\"></r>, <r v=\"Rom.11.36\"></r> <r v=\"Rom.16.27\"></r>, <r v=\"Gal.1.5\"></r>, <r v=\"Eph.3.21\"></r>, al. </s> <s n=\"3.\">Later also (not cl.) as in LXX (= <h n=\"H1935\">הוֹד</h>, <r v=\"Job.39.20\"></r>, <r v=\"1Chr.29.25\"></r>; <h n=\"H3519\">כָּבֹוד</h>, <r v=\"Job.19.9\"></r>, <r v=\"Esth.5.11\"></r>, al.), visible <b>brightness, splendour, glory</b>: of light, <r v=\"Acts.22.11\"></r>; of heavenly bodies, <r v=\"1Cor.15.40\"></r><i> ff. </i>; esp. that wh. radiates from God's presence, as manifested in the pillar of cloud and in the Holy of Holies (= <h n=\"H3519\">כָּבוֹד</h>, <r v=\"Exod.16.10\"></r> <r v=\"Exod.25.22\"></r> <r v=\"Exod.40.34\"></r>, al.; and new Heb. <h n=\"H7914\">שְׁכִינָה</h>, <r v=\"2Macc.2.8\"></r>; v. <i>DB</i>, iv, 489<i>b</i>), <r v=\"Rom.9.4\"></r>, <r v=\"Jas.2.1\"></r> (v. Hort, Mayor, in l.); hence of the manifested glory of God, <r v=\"Rom.1.23\"></r>, <r v=\"Col.1.11\"></r> <r v=\"Eph.1.6\"></r>, <r v=\"Eph.1.12\"></r>, <r v=\"Eph.1.17\"></r> <r v=\"Eph.3.16\"></r>; of the same as communicated to man through Christ, <r v=\"2Cor.3.18\"></r> <r v=\"2Cor.4.6\"></r>; and of the glorious condition into which Christians shall enter hereafter, <r v=\"Rom.8.18\"></r>, <r v=\"Rom.8.21\"></r> <r v=\"Rom.9.23\"></r>, <r v=\"2Tim.2.10\"></r>, al. </s> </s> <sy><i>SYN.</i>: <g>ἔπαινος τιμή</g> (v. Hort on <r v=\"1Pet.1.7\"></r>).</sy>"},"G1325":{"l":"δίδωμι","o":415,"ar":"<f><o>δίδωμι</o>، </f> <s><b>يعطي</b> — بمعانٍ متنوعة بحسب السياق — <b>يمنح، يهب، يزوّد، يسلّم، يستودع، يُثمر (يُخرج)</b>: مطلقًا، <r v=\"Acts.20.35\"></r>؛ مع منصوب الشيء وقابل الشخص، <r v=\"Matt.4.9\"></r> <r v=\"Matt.5.31\"></r>، <r v=\"John.1.12\"></r>، وفي مواضع أخرى كثيرة؛ مع قابل الشخص، يليه <g>ἐκ</g>، <r v=\"Matt.25.8\"></r>؛ وكذلك مع المضاف إليه التبعيضي، <r v=\"Rev.2.17\"></r>؛ مع منصوب الشخص، <r v=\"John.3.16\"></r>، <r v=\"Rev.20.13\"></r>، وفي مواضع أخرى؛ <g>δεξιάς</g>، <r v=\"Gal.2.9\"></r>؛ <g>φίλημα</g>، <r v=\"Luke.7.45\"></r>؛ <g>γνῶσιν</g>، <r v=\"Luke.1.77\"></r>؛ <g>κρίσιν</g>، <r v=\"John.5.22\"></r>؛ عن البذر يعطي ثمرًا، <r v=\"Mark.4.7\"></r>، 8؛ <g>ἐργασίαν</g>، <r v=\"Luke.12.58\"></r>؛ مع مصدر الغاية، <r v=\"Matt.27.34\"></r>، <r v=\"Mark.5.43\"></r>، <r v=\"Luke.8.55\"></r>، <r v=\"John.6.52\"></r>، وفي مواضع أخرى؛ مع قابل الشخص والمصدر، <r v=\"Luke.1.74\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Acts.2.27\"></r>، <r v=\"Rev.3.9\"></r>؛ مع مفعولين منصوبين، <r v=\"Matt.20.28\"></r>، <r v=\"Mark.10.45\"></r>، <r v=\"Eph.1.22\"></r> <r v=\"Eph.4.11\"></r>، <r v=\"2Thess.3.9\"></r>، <r v=\"1Tim.2.6\"></r>، وفي مواضع أخرى؛ <g>ἑαυτὸν δ. εἰς</g> (بوليبيوس، وغيره)، <r v=\"Acts.19.31\"></r>؛ مع قابل الشخص، يليه <g>κατά</g>، <r v=\"Rev.2.28\"></r> <i>(السبعينية)</i>؛ <g>δ. ἵνα</g>، <r v=\"Rev.3.9\"></r>؛ <g>δέδωκα ἐνώπιόν σου θύραν ἀνεῳγμένην</g>، <r v=\"Rev.3.8\"></r>.</s>","en":"<f><o>δίδωμι</o>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5414\">נתן</h> (53 words in all) ;]</e> </et> <s><b>to give</b>—in various senses, acc. to context—<b>bestow, grant, supply, deliver, commit, yield</b>: absol., <r v=\"Acts.20.35\"></r>; c. acc. rei et dat. pers., <r v=\"Matt.4.9\"></r> <r v=\"Matt.5.31\"></r>, <r v=\"John.1.12\"></r>, al. mult.; c. dat. pers., seq. <g>ἐκ</g>, <r v=\"Matt.25.8\"></r>; id. c. gen. part.. <r v=\"Rev.2.17\"></r>; c. acc. pers., <r v=\"John.3.16\"></r>, <r v=\"Rev.20.13\"></r>, al.; <g>δεξιάς</g>, <r v=\"Gal.2.9\"></r>; <g>φίλημα</g>, <r v=\"Luke.7.45\"></r>; <g>γνῶσιν</g>, <r v=\"Luke.1.77\"></r>; <g>κρίσιν</g>, <r v=\"John.5.22\"></r>; of seed yielding fruit, <r v=\"Mark.4.7\"></r>, 8; <g>ἐργασίαν</g> (Deiss., <i>LAE</i>, 117f.), <r v=\"Luke.12.58\"></r>; c. inf. fin., <r v=\"Matt.27.34\"></r>, <r v=\"Mark.5.43\"></r>, <r v=\"Luke.8.55\"></r>, <r v=\"John.6.52\"></r>, al.; c. dat. pers. et inf., <r v=\"Luke.1.74\"></r>, al.; c. acc. et inf., <r v=\"Acts.2.27\"></r>, <r v=\"Rev.3.9\"></r>; c. dupl. acc., <r v=\"Matt.20.28\"></r>, <r v=\"Mark.10.45\"></r>, <r v=\"Eph.1.22\"></r> <r v=\"Eph.4.11\"></r>, <r v=\"2Thess.3.9\"></r>, <r v=\"1Tim.2.6\"></r>, al.; <g>ἑαυτὸν δ. εἰς</g> (Polyb., al.), <r v=\"Acts.19.31\"></r>; c. dat. pers., seq. <g>κατά</g> (MM, <i>Exp.</i>, xi), <r v=\"Rev.2.28\"></r> <i>(LXX)</i>; <g>δ. ἵνα</g>, <r v=\"Rev.3.9\"></r>; <g>δέδωκα ἐνώπιόν σου θύραν ἀνεῳγμένην</g>, <r v=\"Rev.3.8\"></r>.</s> <sy><i>SYN.</i>: <g>δωρέομαι</g>.</sy>"},"G1320":{"l":"διδάσκαλος","o":59,"ar":"<f>* <o>διδάσκαλος</o>، <g>-ου, ὁ</g></f> <s>يَرِد ترجمةً للعبرية <h n=\"????\">רַבּוֺן</h>، <h n=\"????\">רַבִּי</h> (في العهد الجديد: <g>Ῥαββεί</g>، <g>Ῥαββουνεί</g>، انظره)؛ </s> <s><b>معلّم</b>: <r v=\"John.1.39\"></r> <r v=\"John.20.16\"></r>؛ عن معلّمي اليهود، <r v=\"Luke.2.46\"></r>، <r v=\"John.3.10\"></r>، قارن <r v=\"Rom.2.20\"></r>، <r v=\"Rom.2.21\"></r>؛ عن يوحنا المعمدان، <r v=\"Luke.3.12\"></r>؛ عن يسوع، <r v=\"John.3.2\"></r>، <r v=\"John.3.10\"></r> <r v=\"John.8.4\"></r> <r v=\"John.11.28\"></r> <r v=\"John.13.13\"></r>، <r v=\"John.13.14\"></r>، وكثيرًا في <i>الأناجيل الإزائية</i>، وأكثر ما يكون في النداء لقبًا للمخاطبة، مثل <r v=\"Matt.8.19\"></r>، <r v=\"Mark.4.38\"></r>؛ عن يسوع متكلمًا عن نفسه، <r v=\"Matt.23.8\"></r>؛ عن رسول، <r v=\"1Tim.2.7\"></r>، <r v=\"2Tim.1.11\"></r>؛ عن المسيحيين، <r v=\"1Cor.12.28\"></r>، <r v=\"1Cor.12.29\"></r>، <r v=\"Eph.4.11\"></r>، <r v=\"Acts.13.1\"></r>، <r v=\"Jas.3.1\"></r>؛ عن المعلّمين الكذبة، <r v=\"2Tim.4.3\"></r> </s>","en":"<f>* <o>διδάσκαλος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>διδάσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.6.1\"></r>, <r v=\"2Macc.1.10\"></r> * ;] </e> </et> <s>given as rendering of Heb. <h n=\"????\">רַבּוֺן</h>, <h n=\"????\">רַבִּי</h> (NT, <g>Ῥαββεί</g>, <g>Ῥαββουνεί</g> q.v.); </s> <s><b>a teacher</b>: <r v=\"John.1.39\"></r> <r v=\"John.20.16\"></r>; of Jewish teachers, <r v=\"Luke.2.46\"></r>, <r v=\"John.3.10\"></r>, cf. <r v=\"Rom.2.20\"></r>, <r v=\"Rom.2.21\"></r>; of John Baptist, <r v=\"Luke.3.12\"></r>; of Jesus, <r v=\"John.3.2\"></r>, <r v=\"John.3.10\"></r> <r v=\"John.8.4\"></r> <r v=\"John.11.28\"></r> <r v=\"John.13.13\"></r>, <r v=\"John.13.14\"></r>, and often in <i>Syn.</i>, most freq. in voc., as title of address, as <r v=\"Matt.8.19\"></r>, <r v=\"Mark.4.38\"></r>; of Jesus by himself, <r v=\"Matt.23.8\"></r>; of an apostle, <r v=\"1Tim.2.7\"></r>, <r v=\"2Tim.1.11\"></r>; of Christians, <r v=\"1Cor.12.28\"></r>, <r v=\"1Cor.12.29\"></r>, <r v=\"Eph.4.11\"></r>, <r v=\"Acts.13.1\"></r>, <r v=\"Jas.3.1\"></r>; of false teachers, <r v=\"2Tim.4.3\"></r> (Cremer, 181; <i>DB</i>, i, 609, iii, 294, iv, 691) </s> <sy><i>SYN.</i>: <g>παιδευτής</g>, q.v.</sy>"},"G1319":{"l":"διδασκαλία","o":21,"ar":"<f><o>διδασκαλία</o>، <g>-ας, ἡ</g></f> <s><b>تعليم، إرشاد</b>، بالمعنيين الفاعلي (فعل التعليم) والمفعولي (ما يُعلَّم)، والثاني هو الأكثر: <r v=\"Rom.12.7\"></r> <r v=\"Rom.15.4\"></r>، <r v=\"Eph.4.14\"></r>، <r v=\"1Tim.4.6\"></r>، <r v=\"1Tim.4.13\"></r>، <r v=\"1Tim.4.16\"></r> <r v=\"1Tim.5.17\"></r> <r v=\"1Tim.6.1\"></r>، <r v=\"1Tim.6.3\"></r>، <r v=\"2Tim.3.10\"></r>، <r v=\"2Tim.3.16\"></r>، <r v=\"Titus.2.7\"></r>، <r v=\"Titus.2.10\"></r>؛ <g>ὑγιαινοῦσα δ.</g>، <r v=\"1Tim.1.10\"></r>، <r v=\"2Tim.4.3\"></r>، <r v=\"Titus.1.9\"></r> <r v=\"Titus.2.1\"></r>؛ جمع، <g>δ. τ. ἀνθρώπων</g>، <r v=\"Col.2.22\"></r>؛ <g>δ. δαιμονίων</g>، <r v=\"1Tim.4.1\"></r>، <g>δ. διδάσκειν</g>، <r v=\"Matt.15.9\"></r>، <r v=\"Mark.7.7\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>διδασκαλία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διδάσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.2.17\"></r> (<h n=\"H441\">אַלּוּף</h>), <r v=\"Isa.29.13\"></r> (<h n=\"H3925\">למד</h> pu.), <r v=\"Sir.24.33\"></r> <r v=\"Sir.39.8\"></r> * ;] </e> </et> <s><b>teaching, instruction</b>, in both active and objective senses, most freq. the latter: <r v=\"Rom.12.7\"></r> <r v=\"Rom.15.4\"></r>, <r v=\"Eph.4.14\"></r>, <r v=\"1Tim.4.6\"></r>, <r v=\"1Tim.4.13\"></r>, <r v=\"1Tim.4.16\"></r> <r v=\"1Tim.5.17\"></r> <r v=\"1Tim.6.1\"></r>, <r v=\"1Tim.6.3\"></r>, <r v=\"2Tim.3.10\"></r>, <r v=\"2Tim.3.16\"></r>, <r v=\"Titus.2.7\"></r>, <r v=\"Titus.2.10\"></r>; <g>ὑγιαινοῦσα δ.</g>, <r v=\"1Tim.1.10\"></r>, <r v=\"2Tim.4.3\"></r>, <r v=\"Titus.1.9\"></r> <r v=\"Titus.2.1\"></r>; pl., <g>δ. τ. ἀνθρώπων</g>, <r v=\"Col.2.22\"></r>; <g>δ. δαιμονίων</g>, <r v=\"1Tim.4.1\"></r>, <g>δ. διδάσκειν</g>, <r v=\"Matt.15.9\"></r>, <r v=\"Mark.7.7\"></r> <i>(LXX)</i> (Cremer, 182).†</s> <sy><i>SYN.</i>: <g>διδαχή</g> </sy>"},"G1378":{"l":"δόγμα","o":5,"ar":"<f><o>δόγμα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>رأي</b>. </s> <s n=\"2.\"><b>مرسوم، فريضة</b> عامة: عن الحكّام الرومان، <r v=\"Luke.2.1\"></r>، <r v=\"Acts.17.7\"></r>؛ عن الناموس اليهودي، <r v=\"Eph.2.15\"></r>، <r v=\"Col.2.14\"></r>؛ عن الرسل، <r v=\"Acts.16.4\"></r>.†</s>","en":"<f><o>δόγμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>δοκέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1881\">דָּת</h>, <h n=\"H2942\">טְעֵם</h> ;] </e> </et> <s n=\"1.\"><b>an opinion</b>. </s> <s n=\"2.\">A public <b>decree, ordinance</b>: of Roman rulers, <r v=\"Luke.2.1\"></r>, <r v=\"Acts.17.7\"></r>; of the Jewish law, <r v=\"Eph.2.15\"></r>, <r v=\"Col.2.14\"></r>; of the Apostles, <r v=\"Acts.16.4\"></r> (Cremer, 205).†</s>"},"G1343":{"l":"δικαιοσύνη","o":92,"ar":"<f><o>δικαιοσύνη</o>، <g>-ης, ἡ</g></f> <s>صفة <g>ὁ δίκαιος</g> (انظره) </s> <s n=\"1.\">بالمعنى الواسع: <b>البر</b>، أي المطابقة للمشيئة الإلهية في القصد والفكر والعمل: <r v=\"Matt.5.6\"></r>، <r v=\"John.16.8\"></r>، <r v=\"Acts.13.10\"></r>، <r v=\"Rom.4.3\"></r>؛ <g>λόγος δικαιοσύνης</g>، <b>تعليم</b> البر، <r v=\"Heb.5.13\"></r>؛ <g>βασιλεὺς δ.</g>، <r v=\"Heb.7.2\"></r>؛ <g>ὅπλα δ.</g>، <r v=\"Rom.6.13\"></r>؛ <g>ὁδὸς δ.</g>، <r v=\"Matt.21.32\"></r>؛ <g>θώραξ τῆς δ.</g>، <r v=\"Eph.6.14\"></r>؛ <g>διὰκονοι δ.</g>، <r v=\"2Cor.11.15\"></r>؛ <g>ὁσιότης καὶ δ.</g>، <r v=\"Luke.1.75\"></r>، قارن <r v=\"Eph.4.24\"></r>؛ <g>ἀγαθωσύνῃ καὶ δ.</g>، <r v=\"Eph.5.9\"></r>؛ <g>δ. κ. εἰρήνη κ. χαρά</g>، <r v=\"Rom.14.17\"></r>؛ <g>δ. κ. ἁγιασμός</g>، <r v=\"1Cor.1.30\"></r>؛ عكس <g>ἁμαρτία</g>، <r v=\"Rom.8.10\"></r>؛ <g>ἀνομία</g>، <r v=\"2Cor.6.14\"></r>؛ <g>άδικία</g>، <r v=\"Rom.3.5\"></r>؛ <g>ποιεῖν τὴν δ.</g>، <r v=\"1John.2.29\"></r> <r v=\"1John.3.7\"></r>؛ ونفسه بوصفه لفظًا جامعًا للواجبات العملية في الحياة الدينية، <r v=\"Matt.6.1\"></r>؛ <g>ἐργάζεσθαι δ.</g>، <r v=\"Acts.10.35\"></r>؛ <g>διώκειν δ.</g>، <r v=\"1Tim.6.11\"></r>؛ <g>πληροῦν πᾶσαν δ.</g>، <r v=\"Matt.3.15\"></r>؛ <g>ζῆν τῇ δ.</g>، <r v=\"1Pet.2.24\"></r>؛ <g>δ. θεοῦ</g>، برٌّ إلهي في طبيعته ومصدره، <r v=\"Matt.6.33\"></r>، <r v=\"Jas.1.20\"></r>، رومية (حيث يتضمن أيضًا فكرة بر الله الشخصي؛ قارن <r v=\"Rom.1.17\"></r>) <r v=\"Rom.1.17\"></r> <r v=\"Rom.3.5\"></r>، <r v=\"Rom.3.21-Rom.3.26\"></r> <r v=\"Rom.10.3\"></r>، <r v=\"2Cor.5.21\"></r>، <r v=\"Phil.3.9\"></r>؛ <g>ἡ δ. τ. πίσιεως</g>، <r v=\"Rom.4.11\"></r>؛ <g>ἡ ἐκ π. δ.</g>، <r v=\"Rom.9.30\"></r>؛ <g>ἡ κατὰ π. δ.</g>، <r v=\"Heb.11.7\"></r>؛ ويقابل هذا <g>ἡ ἐκ νόμου δ.</g>، <r v=\"Rom.10.5\"></r>؛ <g>ἡ δ. ἐν ν.</g>، <r v=\"Phil.3.6\"></r>؛ <g>ἡ ἰδία δ.</g>، <r v=\"Rom.10.3\"></r>، قارن <r v=\"Phil.3.9\"></r> </s> <s n=\"2.\">بمعنى أضيق (قارن <g>δίκαιος</g>)، <b>العدل</b>: <r v=\"Acts.17.31\"></r>، <r v=\"2Pet.1.1\"></r>، <r v=\"Rev.19.11\"></r> .</s>","en":"<f><o>δικαιοσύνη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>δίκαιος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6664\">צֶדֶק</h>, and cognates, <r v=\"Gen.15.6\"></r>, al., rarely for <h n=\"H2617\">חֶסֶד</h>, <r v=\"Gen.19.19\"></r> ;]</e> </et> <s>the character of <g>ὁ δίκαιος</g> (q.v.) </s> <s n=\"1.\">in broad sense, <b>righteousness</b>, conformity to the Divine will in purpose, thought and action: <r v=\"Matt.5.6\"></r>, <r v=\"John.16.8\"></r>, <r v=\"Acts.13.10\"></r>, <r v=\"Rom.4.3\"></r>; <g>λόγος δικαιοσύνης</g>, <b>teaching of</b> r., <r v=\"Heb.5.13\"></r>; <g>βασιλεὺς δ.</g> (cf. FlJ, <i>BJ</i>, vi, 10, <g>β. δίκαιος</g>), <r v=\"Heb.7.2\"></r>; <g>ὅπλα δ.</g>, <r v=\"Rom.6.13\"></r>; <g>ὁδὸς δ.</g>, <r v=\"Matt.21.32\"></r>; <g>θώραξ τῆς δ.</g>, <r v=\"Eph.6.14\"></r>; <g>διὰκονοι δ.</g>, <r v=\"2Cor.11.15\"></r>; <g>ὁσιότης καὶ δ.</g>, <r v=\"Luke.1.75\"></r>, cf. <r v=\"Eph.4.24\"></r>; <g>ἀγαθωσύνῃ καὶ δ.</g>, <r v=\"Eph.5.9\"></r>; <g>δ. κ. εἰρήνη κ. χαρά</g>, <r v=\"Rom.14.17\"></r>; <g>δ. κ. ἁγιασμός</g>, <r v=\"1Cor.1.30\"></r>; opp. to <g>ἁμαρτία</g>, <r v=\"Rom.8.10\"></r>; <g>ἀνομία</g>, <r v=\"2Cor.6.14\"></r>; <g>άδικία</g>, <r v=\"Rom.3.5\"></r>; <g>ποιεῖν τὴν δ.</g>, <r v=\"1John.2.29\"></r> <r v=\"1John.3.7\"></r>; id. as an inclusive term for the active duties of the religious life (<i>ICC</i>, in l.; Abbott, <i>Essays</i>, 73 ff), <r v=\"Matt.6.1\"></r>; <g>ἐργάζεσθαι δ.</g>, <r v=\"Acts.10.35\"></r>; <g>διώκειν δ.</g>, <r v=\"1Tim.6.11\"></r>; <g>πληροῦν πᾶσαν δ.</g>, <r v=\"Matt.3.15\"></r>; <g>ζῆν τῇ δ.</g>, <r v=\"1Pet.2.24\"></r>; <g>δ. θεοῦ</g>, a righteousness divine in its character and origin, <r v=\"Matt.6.33\"></r>, <r v=\"Jas.1.20\"></r>, Ro (where it also includes the idea of God's personal r.; v. <i>ICC</i>, on <r v=\"Rom.1.17\"></r>) <r v=\"Rom.1.17\"></r> <r v=\"Rom.3.5\"></r>, <r v=\"Rom.3.21-Rom.3.26\"></r> <r v=\"Rom.10.3\"></r>, <r v=\"2Cor.5.21\"></r>, <r v=\"Phil.3.9\"></r>; <g>ἡ δ. τ. πίσιεως</g>, <r v=\"Rom.4.11\"></r>; <g>ἡ ἐκ π. δ.</g>, <r v=\"Rom.9.30\"></r>; <g>ἡ κατὰ π. δ.</g>, <r v=\"Heb.11.7\"></r>; opp. to this is <g>ἡ ἐκ νόμου δ.</g>, <r v=\"Rom.10.5\"></r>; <g>ἡ δ. ἐν ν.</g>, <r v=\"Phil.3.6\"></r>; <g>ἡ ἰδία δ.</g>, <r v=\"Rom.10.3\"></r>, cf. <r v=\"Phil.3.9\"></r> </s> <s n=\"2.\">In narrower sense (cf. <g>δίκαιος</g>), <b>justice</b>: <r v=\"Acts.17.31\"></r>, <r v=\"2Pet.1.1\"></r>, <r v=\"Rev.19.11\"></r> (<i>DCG</i>, ii, 529 ff.; Cremer, 190, 690).</s>"},"G1321":{"l":"διδάσκω","o":97,"ar":"<f><o>διδάσκω</o> </f> <s><b>يعلّم</b> (أي <b>يرشد</b>) شخصًا، <b>يعلّم</b> شيئًا؛ <s n=\"1.\">متعدٍّ: مع منصوب الشخص، <r v=\"Matt.5.2\"></r>، <r v=\"Mark.1.22\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Mark.8.31\"></r>؛ <g>περί</g>، <r v=\"1John.2.27\"></r>؛ مع المصدر، <r v=\"Luke.11.1\"></r>؛ مع منصوب الشيء، <r v=\"Mark.6.30\"></r> <r v=\"Mark.12.14\"></r>؛ مع المفعول المطلق المجانس، <r v=\"Matt.15.9\"></r> (السبعينية)؛ مع مفعولين منصوبين، <r v=\"Mark.4.2\"></r>، <r v=\"John.14.26\"></r>؛ مبني للمجهول، <r v=\"Gal.1.12\"></r>، <r v=\"2Thess.2.15\"></r>؛ مع قابل الشخص (كما في العبرية، قارن <r v=\"Job.21.22\"></r>)، <r v=\"Rev.2.14\"></r>. </s> <s n=\"2.\">مطلقًا (بلا مفعول)، <b>يعلّم، يقدّم تعليمًا</b>: <r v=\"Matt.4.23\"></r>، <r v=\"Mark.1.21\"></r>، وكثيرًا في الأناجيل، <r v=\"Rom.12.7\"></r>، <r v=\"1Cor.4.17\"></r>، <r v=\"1Tim.2.12\"></r>، وفي مواضع أخرى. </s> </s>","en":"<f><o>διδάσκω</o> </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3925\">למד</h> pi., also for <h n=\"H3045\">ידע</h> hi., <h n=\"H3384\">ירה</h> hi., etc. ;]</e> </et> <s><b>to teach</b> (i.e. <b>instruct</b>) a person, <b>teach</b> a thing; <s n=\"1.\">trans.: c. acc. pers., <r v=\"Matt.5.2\"></r>, <r v=\"Mark.1.22\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Mark.8.31\"></r>; <g>περί</g>, <r v=\"1John.2.27\"></r>; c. inf., <r v=\"Luke.11.1\"></r>; c. acc. rei, <r v=\"Mark.6.30\"></r> <r v=\"Mark.12.14\"></r>; c. cogn. acc., <r v=\"Matt.15.9\"></r> (LXX); c. dupl. acc, <r v=\"Mark.4.2\"></r>, <r v=\"John.14.26\"></r>; pass., <r v=\"Gal.1.12\"></r>, <r v=\"2Thess.2.15\"></r>; c. dat. pers. (like Heb., cf. <r v=\"Job.21.22\"></r>, but prob. a vernac. usage, v. Swete, in l.), <r v=\"Rev.2.14\"></r>. </s> <s n=\"2.\">Absol., <b>to teach, give instruction</b>: <r v=\"Matt.4.23\"></r>, <r v=\"Mark.1.21\"></r>, and often in Gosp., <r v=\"Rom.12.7\"></r>, <r v=\"1Cor.4.17\"></r>, <r v=\"1Tim.2.12\"></r>, al. </s> </s> <sy><i>SYN.</i>: <g>παιδεύω</g> (cf. Westc., <i>Heb.</i>, 402; Cremer, 180).</sy>"},"G1346":{"l":"δικαίως","o":5,"ar":"<f><o>δικαίως </o></f> ظرف <s n=\"1.\"><b>ببرّ</b>: <r v=\"1Cor.15.34\"></r>، <r v=\"1Thess.2.10\"></r>، <r v=\"Titus.2.12\"></r>. </s> <s n=\"2.\"><b>بعدل، بحق</b>: <r v=\"Luke.23.41\"></r>، <r v=\"1Pet.2.23\"></r>.†</s>","en":"<f><o>δικαίως </o></f> adv. <et> <e t=\"derivation\">(&lt; <g>δίκαιος</g>, q.v.), </e> <e t=\"septuagint\">[in LXX for <h n=\"H6664\">צֶדֶק</h>, etc. ;] </e> </et> <s n=\"1.\"><b>righteously</b>: <r v=\"1Cor.15.34\"></r>, <r v=\"1Thess.2.10\"></r>, <r v=\"Titus.2.12\"></r>. </s> <s n=\"2.\"><b>justly</b>: <r v=\"Luke.23.41\"></r>, <r v=\"1Pet.2.23\"></r>.†</s>"},"G1370":{"l":"διχοστασία","o":2,"ar":"<f>** <o>διχοστασία</o>، <g>-ας, ἡ</g></f> <s><b>انقسام، شقاق</b>: <r v=\"Rom.16.17\"></r>، <r v=\"Gal.5.20\"></r>.†</s>","en":"<f>** <o>διχοστασία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διχοστατέω</g>, <b>to stand apart</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.3.29\"></r> * ;] </e> </et> <s><b>standing apart, dissension</b>: <r v=\"Rom.16.17\"></r>, <r v=\"Gal.5.20\"></r>.†</s>"},"G1308":{"l":"διαφέρω","o":13,"ar":"<f><o>δια-φέρω </o></f> <s n=\"1.\">متعدٍّ، </s> <s n=\"(a)\"><b>يحمل عبر</b>: يليه <g>διά</g>، <r v=\"Mark.11.16\"></r>؛ </s> <s n=\"(b)\"><b>يحمل هنا وهناك، يذيع، ينشر</b>: المبني للمجهول، <r v=\"Acts.13.49\"></r> <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">لازم، </s> <s n=\"(a)\"><b>يختلف</b>: <g>τὰ διαφέροντα</g>، <r v=\"Rom.2.18\"></r>، <r v=\"Phil.1.10\"></r> (الترجمة المنقحة، الهامش؛ لكن انظر أدناه)؛ غير شخصي، <g>διαφέρει</g>، <b>يُحدث فرقًا، يهمّ</b>: <r v=\"Gal.2.6\"></r>؛ </s> <s n=\"(b)\"><b>يفوق، يتميّز</b>: مع المضاف إليه <r v=\"Matt.6.26\"></r> <r v=\"Matt.10.31\"></r> <r v=\"Matt.12.12\"></r>، <r v=\"Luke.12.7\"></r>، <r v=\"Luke.12.24\"></r>، <r v=\"1Cor.15.41\"></r>، <r v=\"Gal.4.1\"></r>؛ <g>τὰ διαφέροντα</g>، <r v=\"Rom.2.18\"></r>، <r v=\"Phil.1.10\"></r> (الترجمة المنقحة، المتن؛ قارن <r v=\"Rom.2.18\"></r>، <r v=\"Phil.1.10\"></r>).†</s>","en":"<f><o>δια-φέρω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8133\">שְׁנָא</h> (<r v=\"Dan.7\"></r> only); <r v=\"1Sam.17.39\"></r>, <r v=\"Ezra.3.13\"></r>, al. ;]</e> </et> <s n=\"1.\">trans., </s> <s n=\"(a)\"><b>to carry through</b>: seq. <g>διά</g>, <r v=\"Mark.11.16\"></r>; </s> <s n=\"(b)\"><b>to carry about, spread abroad</b>: pass., <r v=\"Acts.13.49\"></r> <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">Intrans., </s> <s n=\"(a)\"><b>to differ</b>: <g>τὰ διαφέροντα</g>, <r v=\"Rom.2.18\"></r>, <r v=\"Phil.1.10\"></r> (R, mg., but v. infr.); impers., <g>διαφέρει</g>, <b>it makes a difference, it matters</b>: <r v=\"Gal.2.6\"></r>; </s> <s n=\"(b)\"><b>to excel</b>: c. gen. <r v=\"Matt.6.26\"></r> <r v=\"Matt.10.31\"></r> <r v=\"Matt.12.12\"></r>, <r v=\"Luke.12.7\"></r>, <r v=\"Luke.12.24\"></r>, <r v=\"1Cor.15.41\"></r>, <r v=\"Gal.4.1\"></r>; <g>τὰ διαφέροντα</g>, <r v=\"Rom.2.18\"></r>, <r v=\"Phil.1.10\"></r> (R, txt.; for discussion and reff. v. <i>ICC</i> on <r v=\"Rom.2.18\"></r>, <r v=\"Phil.1.10\"></r>, ll. c.).†</s>"},"G1372":{"l":"διψάω","o":16,"ar":"<f><o>διψάω,-ῶ</o></f> <s><b>يعطش</b>: مطلقًا، <r v=\"Matt.25.35\"></r>، <r v=\"Matt.25.37\"></r>، <r v=\"Matt.25.42\"></r>، <r v=\"Matt.25.44\"></r>، <r v=\"John.4.13\"></r>، <r v=\"John.4.15\"></r> <r v=\"John.19.28\"></r>، <r v=\"Rom.12.20\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.4.11\"></r>؛ مجازيًا، <r v=\"John.4.14\"></r> <r v=\"John.6.35\"></r> <r v=\"John.7.37\"></r>، <r v=\"Rev.7.16\"></r> <r v=\"Rev.21.6\"></r> <r v=\"Rev.22.17\"></r>؛ مع المنصوب (وفي الكلاسيكية مع المضاف إليه)، <g>τ. δικαιοσύνην</g>، <r v=\"Matt.5.6\"></r>.†</s>","en":"<f><o>διψάω,-ῶ</o></f> <et> <e t=\"derivation\">(&lt; <g>δίψα</g>, thirst), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6770\">צָמֵא</h> ;] </e> </et> <s><b>to thirst</b>: absol., <r v=\"Matt.25.35\"></r>, <r v=\"Matt.25.37\"></r>, <r v=\"Matt.25.42\"></r>, <r v=\"Matt.25.44\"></r>, <r v=\"John.4.13\"></r>, <r v=\"John.4.15\"></r> <r v=\"John.19.28\"></r>, <r v=\"Rom.12.20\"></r> <i>(LXX)</i>, <r v=\"1Cor.4.11\"></r>; fig., <r v=\"John.4.14\"></r> <r v=\"John.6.35\"></r> <r v=\"John.7.37\"></r>, <r v=\"Rev.7.16\"></r> <r v=\"Rev.21.6\"></r> <r v=\"Rev.22.17\"></r>; c. acc (= cl. c. gen.), <g>τ. δικαιοσύνην</g>, <r v=\"Matt.5.6\"></r>.†</s>"},"G1389":{"l":"δολόω","o":1,"ar":"<f><o>δολόω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>يوقع في شَرَك، يخدع</b>. </s> <s n=\"2.\">كما يُغَشّ الخمر: <b>يغشّ، يُفسِد</b>: <g>τ. λόγον τ. θεοῦ</g>، <r v=\"2Cor.4.2\"></r>.†</s>","en":"<f><o>δολόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(<g>δόλος</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.15.3\"></r> (<h n=\"H7270\">רגל</h>), <r v=\"Ps.36.2\"></r> (<h n=\"H2505\">חלק</h> hi.) * ;] </e> </et> <s n=\"1.\"><b>to ensnare</b>. </s> <s n=\"2.\">As of wine, <b>to adulterate, corrupt</b>: <g>τ. λόγον τ. θεοῦ</g>, <r v=\"2Cor.4.2\"></r>.†</s> <sy><i>SYN.</i>: <g>καπηλεύω</g> q.v.</sy>"},"G1382":{"l":"δοκιμή","o":7,"ar":"<f>*† <o>δοκιμή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">عملية الامتحان: <b>اختبار، امتحان</b>: <r v=\"2Cor.8.2\"></r>، <r v=\"2Cor.9.13\"></r>. </s> <s n=\"2.\">نتيجة الامتحان: <b>تزكية، كون الشخص مزكًّى، برهان</b>: <r v=\"Rom.5.4\"></r>، <r v=\"2Cor.2.9\"></r>، <r v=\"2Cor.13.3\"></r>، <r v=\"Phil.2.22\"></r>.†</s>","en":"<f>*† <o>δοκιμή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>δόκιμος</g>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"Ps.68.31\"></r> * ;] </e> </et> <s n=\"1.\">the process of trial, <b>proving, test</b>: <r v=\"2Cor.8.2\"></r> <r v=\"2Cor.9.13\"></r>. </s> <s n=\"2.\">The result of trial, <b>approval, approvedness, proof</b> : <r v=\"Rom.5.4\"></r>, <r v=\"2Cor.2.9\"></r> <r v=\"2Cor.13.3\"></r>, <r v=\"Phil.2.22\"></r> (Cremer, 212, 701).†</s>"},"G1387":{"l":"δολιόω","o":1,"ar":"<f>† <o>δολιόω</o></f> <s><b>خدع، مكر</b>: <g>ἐδολιοῦσαν</g> (<g>-σαν</g>، صيغة شائعة في اليونانية المتأخرة لضمير الغائبين الجمع في الماضي الناقص): <r v=\"Rom.3.13\"></r> <i>(السبعينية)</i>.†</s>","en":"<f>† <o>δολιόω</o></f> <et> <e t=\"derivation\">(&lt; <g>δόλιος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Num.25.18\"></r>, <r v=\"Ps.105.25\"></r> (<h n=\"H5230\">נָכַל</h>), <r v=\"Ps.5.6\"></r> (<h n=\"H2505\">חָלַק</h> hi.) * ;] </e> </et> <s><b>to deceive</b>: <g>ἐδολιοῦσαν</g> (<g>-σαν</g>, freq. in <g>κοινή</g> Gk. for impf. 3rd pers. pl.), <r v=\"Rom.3.13\"></r> <i>(LXX)</i>.†</s>"},"G1344":{"l":"δικαιόω","o":39,"ar":"<f><o>δικαιόω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: </s> <s n=\"(a)\">مع منصوب الشيء، <b>عدّه صوابًا</b>؛ </s> <s n=\"(b)\">مع منصوب الشخص، <b>أنصف أحدًا</b>؛ المبني للمجهول <g>δικαιοῦσθαι</g>: <b>عومل بالعدل</b>، عكس <g>ἀδικεῖσθαι</g>. </s> <s n=\"2.\">في العهد الجديد، كما في السبعينية، وكما هو المعتاد في الأفعال المنتهية بـ<g>-όω</g> المشتقة من صفات ذات معنى أخلاقي؛ </s> <s n=\"(1)\"><b>أظهر أنه بارّ</b>: <r v=\"Matt.11.19\"></r>، <r v=\"Luke.7.35\"></r>، <r v=\"Rom.3.4\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.3.16\"></r>؛ </s> <s n=\"(2)\"><b>برّر، أعلن أو حكم بأنه بارّ</b>: <r v=\"Luke.7.29\"></r>، <r v=\"Luke.10.29\"></r>، <r v=\"Luke.16.15\"></r>، <r v=\"Luke.18.14\"></r>، <r v=\"Rom.2.13\"></r>، <r v=\"Rom.3.24\"></r>، <r v=\"Rom.3.26\"></r>، <r v=\"Rom.3.28\"></r>، <r v=\"Rom.4.5\"></r>، <r v=\"Rom.8.30\"></r>، <r v=\"Rom.8.33\"></r>، <r v=\"Titus.3.7\"></r>؛ يليه <g>ἀπό</g>، <r v=\"Matt.11.19\"></r>، <r v=\"Luke.7.35\"></r>، <r v=\"Acts.13.39\"></r>، <r v=\"Rom.6.7\"></r>؛ <g>ἐκ πίστεως</g>، <r v=\"Rom.3.30\"></r>، <r v=\"Rom.5.1\"></r>، <r v=\"Gal.2.16\"></r>، <r v=\"Gal.3.8\"></r>، <r v=\"Gal.3.24\"></r>؛ <g>ἐξ ἔργων</g>، <r v=\"Rom.3.20\"></r> <i>(السبعينية)</i>، <r v=\"Rom.4.2\"></r>، <r v=\"Gal.2.16\"></r>، <r v=\"Jas.2.21\"></r>، <r v=\"Jas.2.24\"></r>، <r v=\"Jas.2.25\"></r>؛ <g>ἐκ τ. λόγων</g>، <r v=\"Matt.12.37\"></r>؛ <g>διὰ τ. πίστεως</g>، <r v=\"Rom.3.30\"></r>؛ مع القابل، <r v=\"Rom.3.24\"></r>، <r v=\"Rom.3.28\"></r>، <r v=\"Titus.3.7\"></r>؛ يليه <g>ἐν</g>، <r v=\"Acts.13.39\"></r>، <r v=\"Rom.3.4\"></r>، <r v=\"Rom.5.9\"></r>، <r v=\"1Cor.4.4\"></r>، <r v=\"1Cor.6.11\"></r>، <r v=\"Gal.2.17\"></r>، <r v=\"Gal.3.11\"></r>، <r v=\"Gal.5.4\"></r>، <r v=\"1Tim.3.16\"></r>.†</s>","en":"<f><o>δικαιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δίκαιος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6663\">צדק</h> pi., hi., (1) as <r v=\"Ezek.16.51\"></r>, <r v=\"Jer.3.11\"></r> (cf. NT usage); (2) as <r v=\"Deut.25.1\"></r>; <r v=\"Exod.23.7\"></r>, <r v=\"Isa.50.8\"></r> ;] </e> </et> <s n=\"1.\">in cl., </s> <s n=\"(a)\">c. acc rei, <b>to deem right</b>; </s> <s n=\"(b)\">c. acc pers., <b>to do one justice</b>; pass., <g>δικαιοῦσθαι</g>, <b>to be treated rightly</b>, opp. to <g>ἀδικεῖσθαι</g>. </s> <s n=\"2.\">In NT, as in LXX, and as usual with verbs in <g>-όω</g> from adjectives of moral meaning; </s> <s n=\"(1)\"><b>to show to be righteous</b>: <r v=\"Matt.11.19\"></r>, <r v=\"Luke.7.35\"></r>, <r v=\"Rom.3.4\"></r> <i>(LXX)</i>, <r v=\"1Tim.3.16\"></r>; </s> <s n=\"(2)\"><b>to declare, pronounce righteous</b>: <r v=\"Luke.7.29\"></r> <r v=\"Luke.10.29\"></r> <r v=\"Luke.16.15\"></r> <r v=\"Luke.18.14\"></r>, <r v=\"Rom.2.13\"></r> <r v=\"Rom.3.24\"></r>, <r v=\"Rom.3.26\"></r>, <r v=\"Rom.3.28\"></r> <r v=\"Rom.4.5\"></r> <r v=\"Rom.8.30\"></r>, <r v=\"Rom.8.33\"></r>, <r v=\"Titus.3.7\"></r>; seq. <g>ἀπό</g>, <r v=\"Matt.11.19\"></r>, <r v=\"Luke.7.35\"></r>, <r v=\"Acts.13.39\"></r>, <r v=\"Rom.6.7\"></r>; <g>ἐκ πίστεως</g>, <r v=\"Rom.3.30\"></r> <r v=\"Rom.5.1\"></r>, <r v=\"Gal.2.16\"></r> <r v=\"Gal.3.8\"></r>, <r v=\"Gal.3.24\"></r>; <g>ἐξ ἔργων</g>, <r v=\"Rom.3.20\"></r> <i>(LXX)</i> <r v=\"Rom.4.2\"></r>, <r v=\"Gal.2.16\"></r>, <r v=\"Jas.2.21\"></r>, <r v=\"Jas.2.24\"></r>, <r v=\"Jas.2.25\"></r>; <g>ἐκ τ. λόγων</g>, <r v=\"Matt.12.37\"></r>; <g>διὰ τ. πίστεως</g>, <r v=\"Rom.3.30\"></r>; c. dat., <r v=\"Rom.3.24\"></r>, <r v=\"Rom.3.28\"></r>, <r v=\"Titus.3.7\"></r>; seq. <g>ἐν</g>, <r v=\"Acts.13.39\"></r>, <r v=\"Rom.3.4\"></r> <r v=\"Rom.5.9\"></r>, <r v=\"1Cor.4.4\"></r> <r v=\"1Cor.6.11\"></r>, <r v=\"Gal.2.17\"></r> <r v=\"Gal.3.11\"></r> <r v=\"Gal.5.4\"></r>, <r v=\"1Tim.3.16\"></r> (v. Cremer, 193, 693; <i>DB</i>, ii, 826 ff.).†</s>"},"G1328":{"l":"διερμηνευτής","o":1,"ar":"<f>*† <o>δι-ερμηνευτής</o>، <g>-οῦ, ὁ</g></f> <s><b>مترجِم</b>: <r v=\"1Cor.14.28\"></r>.†</s><hr><f><o> ἑρμηνευτής </o>، <g>-οῦ, ό</g></f> <s><b>مترجِم</b>: <r v=\"1Cor.14.28\"></r>.†</s>","en":"<f>*† <o>δι-ερμηνευτής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>διερμηνεύω</g>), </e> </et> <s><b>an interpreter</b>: <r v=\"1Cor.14.28\"></r>.†</s><hr><f><o> ἑρμηνευτής </o>, <g>-οῦ, ό</g></f> <et> <e t=\"derivation\">(&lt; <g> ἑρμηνεύω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3887\">לוּץ</h> hi., <r v=\"Gen.42.23\"></r> *;] </e> </et> <s><b>an interpreter</b>: <r v=\"1Cor.14.28\"></r> (WH, mg.).† <i>{Editor note:verse reference has <g>διερμηνευτής</g>, instead of this form}</i></s>"},"G1318":{"l":"διδακτός","o":3,"ar":"<f><o>διδακτός</o>، <g>-ή, -όν</g></f> <s n=\"1.\"><b>ما يمكن تعليمه</b>. </s> <s n=\"2.\"><b>متعلَّم، مُعلَّم</b>؛ مع المضاف إليه للدلالة على مصدر التعليم؛ </s> <s n=\"(a)\">عن الأشخاص: <g>δ. θεοῦ</g>، <r v=\"John.6.45\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(b)\">عن الأشياء، <g>λόγοις δ. πνεύματος</g>، <r v=\"1Cor.2.13\"></r>.†</s>","en":"<f><o>διδακτός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>διδάσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.54.13\"></r> (<h n=\"H3928\">לִמּוּד</h>), <r v=\"1Macc.4.7\"></r> * ;] </e> </et> <s n=\"1.\"><b>that can be taught</b>. </s> <s n=\"2.\"><b>taught</b>; c. gen., of source of teaching (in cl., poët. only); </s> <s n=\"(a)\">of persons: <g>δ. θεοῦ</g>, <r v=\"John.6.45\"></r> <i>(LXX)</i>; </s> <s n=\"(b)\">of things, <g>λόγοις δ. πνεύματος</g>, <r v=\"1Cor.2.13\"></r>.†</s>"},"G1394":{"l":"δόσις","o":2,"ar":"<f><o>δόσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">أصلاً: فعل <b>العطاء</b>: <r v=\"Phil.4.15\"></r>. </s> <s n=\"2.\">موضوعيًّا: <b>عطية</b>: <r v=\"Jas.1.17\"></r>.†</s>","en":"<f><o>δόσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(<g>δίδωμι</g>) </e> <e t=\"septuagint\">[in LXX for <h n=\"H2706\">חֹק</h> (<r v=\"Gen.47.22\"></r>), <h n=\"H4991\">מַתָּך</h>, <h n=\"H4991\">מַתַּת</h> (<r v=\"Prov.21.14\"></r> <r v=\"Prov.25.14\"></r>), freq. in Si. ;] </e> </et> <s n=\"1.\">properly, the act of <b>giving</b>: <r v=\"Phil.4.15\"></r>. </s> <s n=\"2.\">Objectively, <b>a gift</b>: <r v=\"Jas.1.17\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>δόμα</g></x> </sy>"},"G1311":{"l":"διαφθείρω","o":6,"ar":"<f><o>δια-φθείρω </o></f> <s n=\"1.\"><b>أهلك تمامًا</b>: <r v=\"Luke.12.33\"></r>، <r v=\"Rev.11.18\"></r>؛ المبني للمجهول، <b>هلك، فني</b>: <r v=\"Rev.8.9\"></r>، <r v=\"2Cor.4.16\"></r>. </s> <s n=\"2.\">بالمعنى الأخلاقي: <b>أفسد</b>: <g>τ. γῆν</g>، <r v=\"Rev.11.18\"></r>؛ المبني للمجهول، <g>διεφθαρμένοι τ. νοῦν</g>، <r v=\"1Tim.6.5\"></r>.†</s>","en":"<f><o>δια-φθείρω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7843\">שׁחת</h> hi. ;] </e> </et> <s n=\"1.\"><b>to destroy utterly</b>: <r v=\"Luke.12.33\"></r>, <r v=\"Rev.11.18\"></r>; pass., <b>to be destroyed, disabled</b>: <r v=\"Rev.8.9\"></r>, <r v=\"2Cor.4.16\"></r>. </s> <s n=\"2.\">In moral sense, <b>to corrupt, deprave</b>: <g>τ. γῆν</g>, <r v=\"Rev.11.18\"></r>; pass., <g>διεφθαρμένοι τ. νοῦν</g>, <r v=\"1Tim.6.5\"></r>.†</s>"},"G1384":{"l":"δοκίμιος","o":7,"ar":"<f>† <o>δοκίμιος</o>، <g>-α, -ον</g></f> <s>= <g>δόκιμος</g>، </s> <s><b>مُمتحَن، مُزكّى</b>: <g>τὸ δ. ὑμῶν τ. πίστεως</g>، <b>تزكية إيمانكم، ما هو مُزكّى في إيمانكم</b>، <r v=\"1Pet.1.7\"></r>، <r v=\"Jas.1.3\"></r>.†</s>","en":"<f>† <o>δοκίμιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δοκιμή</g>), </e> <e t=\"septuagint\">[in LXX: <g>ἀργύριον δ.</g> (<h n=\"H5948\">עֲלִיל</h>), <r v=\"Ps.12.6\"></r>; and as v.l. for <g>δόκιμος</g> (B), <g>ἀργυρίου δ.</g> (<h n=\"H2212\">זקק</h> pu.), <r v=\"1Chr.29.4\"></r> (B<i>ab</i>); <g>εἰ δ. ἐστιν</g> (<h n=\"H3366\">יְקָר</h>), <r v=\"Zech.11.13\"></r> <h>א</h> <i>c a vid</i>, Q *)* ;]</e> </et> <s>= <g>δόκιμος</g>, </s> <s><b>tested, approved</b>: <g>τὸ δ. ὑμῶν τ. πίστεως</g>, <b>that which is approved in your faith</b>, <r v=\"1Pet.1.7\"></r> (where Hort suggests the v.l. <g>δόκιμος</g>, found in some cursives), <r v=\"Jas.1.3\"></r> (but v. Mayor, in l. For full discussion of this word, not hitherto found in a Gk. Lexicon, and for exx. of its use in <g>π.</g>, v. Deiss. (to whom is due the credit of its discovery), <i>BS</i>, 259 ff.; MM, <i>Exp.</i>, xi; cf. also Milligan, <i>NTD</i>, 76).†</s>"},"G1364":{"l":"δίς","o":6,"ar":"<f><o>δίς </o></f> ظرف، <s><b>مرتين</b>: <r v=\"Mark.14.30\"></r>، <r v=\"Mark.14.72\"></r>؛ <g>δ. τ. σαββάτου</g> (مرتين في الأسبوع)، <r v=\"Luke.18.12\"></r>؛ <g>καὶ ἅπαξ κ. δ.</g> (مرة ومرتين)، <r v=\"Phil.4.16\"></r>، <r v=\"1Thess.2.18\"></r>؛ <g>δ. ἀποθανόντα</g> (ميتة مضاعفًا)، <r v=\"Jude.1.12\"></r>؛ <g>δ. μυριάδες</g> (ربوتا ربوات)، <r v=\"Rev.9.16\"></r>.†</s>","en":"<f><o>δίς </o></f> adv., <s><b>twice</b>: <r v=\"Mark.14.30\"></r>, <r v=\"Mark.14.72\"></r>; <g>δ. τ. σαββάτου</g>, <r v=\"Luke.18.12\"></r>; <g>καὶ ἅπαξ κ. δ.</g>, <r v=\"Phil.4.16\"></r>, <r v=\"1Thess.2.18\"></r>; <g>δ. ἀποθανόντα</g>, <r v=\"Jude.1.12\"></r> (v. Mayor, <i>ICC</i>, in l.); <g>δ. μυριάδες</g>, <r v=\"Rev.9.16\"></r>.†</s>"},"G1392":{"l":"δοξάζω","o":61,"ar":"<f><o>δοξάζω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يظنّ، يفترض، يرى رأيًا</b>. </s> <s n=\"2.\"><b>يمنح</b> <g>δόξα</g> (انظره) <b>لـ، يعظّم، يُطري، يمدح</b>: مع المنصوب، <r v=\"Matt.5.16\"></r>، <r v=\"Mark.2.12\"></r>، <r v=\"John.8.54\"></r>، <r v=\"Rom.15.6\"></r>، <r v=\"1Pet.2.12\"></r>، وفي مواضع أخرى؛ ونفسه يليه <g>ἐπί</g>، <r v=\"Luke.2.20\"></r>؛ <g>ἐν</g>، <r v=\"Gal.1.24\"></r>، <r v=\"1Pet.4.16\"></r>. </s> <s n=\"3.\">في السبعينية والعهد الجديد (انظر تحت مدخل <g>δόξα</g>، 3): <b>يُلبس بهاءً، يمجّد</b> (<r v=\"Exod.34.29\"></r>، <r v=\"Exod.34.30\"></r>، <r v=\"Ps.37.20\"></r>، <r v=\"Isa.44.23\"></r>، <r v=\"Ezra.3.1\"></r>، وفي مواضع أخرى): <r v=\"Rom.8.30\"></r>، <r v=\"2Cor.3.10\"></r>، <r v=\"2Thess.3.1\"></r>، <r v=\"1Pet.1.8\"></r>، وفي مواضع أخرى؛ عن المسيح، <r v=\"John.7.39\"></r>، <r v=\"John.8.54\"></r>، وفي مواضع أخرى؛ عن الآب، <r v=\"John.13.31\"></r>، <r v=\"John.13.32\"></r>، <r v=\"1Pet.4.11\"></r>، وفي مواضع أخرى (قارن <g>ἐν-</g>، <g>συν-δοξάζω</g>). </s>","en":"<f><o>δοξάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δόξα</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3513\">כּבד</h> ni., pi., also for <h n=\"H6286\">פּאר</h>, etc. ;] </e> </et> <s n=\"1.\"><b>to think, suppose, hold an opinion</b> (Æsch., Plat., al.). </s> <s n=\"2.\">To <b>bestow</b> <g>δόξα</g> (q.v.) <b>on, to magnify, extol, praise</b> (Thuc., iii, 45; Plut., al.): c. acc, <r v=\"Matt.5.16\"></r>, <r v=\"Mark.2.12\"></r>, <r v=\"John.8.54\"></r>, <r v=\"Rom.15.6\"></r>, <r v=\"1Pet.2.12\"></r>, al.; id. seq. <g>ἐπί</g> <r v=\"Luke.2.20\"></r>; <g>ἐν</g>, <r v=\"Gal.1.24\"></r>, <r v=\"1Pet.4.16\"></r>. </s> <s n=\"3.\">In LXX and NT (v.s. <g>δόξα</g>, 3), <b>to clothe with splendour, glorify</b> (<r v=\"Exod.34.29\"></r>, <r v=\"Exod.34.30\"></r>, <r v=\"Ps.37.20\"></r>, <r v=\"Isa.44.23\"></r>, <r v=\"Ezra.3.1\"></r>, al): <r v=\"Rom.8.30\"></r>, <r v=\"2Cor.3.10\"></r>, <r v=\"2Thess.3.1\"></r>, <r v=\"1Pet.1.8\"></r>, al.; of Christ, <r v=\"John.7.39\"></r> <r v=\"John.8.54\"></r>, al. (on the Johannine use, v. Cremer, 211; Westc., <i>Jo.</i>, Intr.); of the Father, <r v=\"John.13.31\"></r>, <r v=\"John.13.32\"></r>, <r v=\"1Pet.4.11\"></r>, al. (cf. <g>ἐν-</g>, <g>συν-δοξάζω</g>). </s>"},"G1341":{"l":"δικαιοκρισία","o":1,"ar":"<f>† <o>δικαιοκρισία</o>، <g>-ας, ἡ </g></f> <s><b>دينونة عادلة</b>: <r v=\"Rom.2.5\"></r> (قارن <g>τ. δικαίας κρίσεως</g>، <r v=\"2Thess.1.5\"></r>؛ <g>τὴν δ. κ.</g>، <r v=\"John.7.24\"></r>).†</s>","en":"<f>† <o>δικαιοκρισία</o>, <g>-ας, ἡ </g></f> <s><b>righteous judgment</b>: <r v=\"Rom.2.5\"></r> (cf. <g>τ. δικαίας κρίσεως</g>, <r v=\"2Thess.1.5\"></r>; <g>τὴν δ. κ.</g>, <r v=\"John.7.24\"></r>. For use in <g>π.</g>, v. Deiss., <i>LAE</i>, 89 f.).†</s>"},"G1313":{"l":"διάφορος","o":4,"ar":"<f><o>διά-φορος</o>، <g>-ον</g></f> <s n=\"1.\"><b>مختلف</b>: <r v=\"Rom.12.6\"></r>، <r v=\"Heb.9.10\"></r>. </s> <s n=\"2.\"><b>ممتاز</b>: صيغة التفضيل <g>-ώτερος</g>، <r v=\"Heb.1.4\"></r>، <r v=\"Heb.8.6\"></r>.†</s>","en":"<f><o>διά-φορος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>διαφέρω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8133\">שְׁנָא</h> (<r v=\"Dan.7.7\"></r>, <r v=\"Dan.7.19\"></r>); also as in Polyb., iv, 18<i>8</i>, al., <g>Τὸ δ., τὰ δ.</g>, <b>money</b>: <r v=\"Sir.27.1\"></r> <r v=\"Sir.42.5\"></r>, <r v=\"2Macc.3.6\"></r> ;] </e> </et> <s n=\"1.\"><b>different</b>: <r v=\"Rom.12.6\"></r>, <r v=\"Heb.9.10\"></r>. </s> <s n=\"2.\"><b>excellent</b>: compar., <g>-ώτερος</g>, <r v=\"Heb.1.4\"></r> <r v=\"Heb.8.6\"></r>.†</s>"},"G1379":{"l":"δογματίζω","o":1,"ar":"<f>† <o>δογματίζω </o></f> <s><b>يُصدر أمرًا (فريضة)</b>. في الصيغة الوسطى: <b>يخضع لفريضة</b>: <r v=\"Col.2.20\"></r>.†</s>","en":"<f>† <o>δογματίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.3.9\"></r> (<h n=\"H3789\">כָּתַב</h> ni.), <r v=\"Dan.2.13\"></r>, <r v=\"Dan.2.15\"></r> (<h n=\"H1883\">דָּתָא</h>, <h n=\"H1881\">דָּת</h>), <r v=\"1Esd.6.34\"></r>, <r v=\"2Macc.10.3\"></r> <r v=\"2Macc.15.36\"></r>, <r v=\"3Macc.4.11\"></r> * ;] </e> </et> <s><b>to decree</b>. Mid., <b>to subject oneself to an ordinance</b>: <r v=\"Col.2.20\"></r>.†</s>"},"G1360":{"l":"διότι","o":23,"ar":"<f><o>δι-ότι </o>، أداة ربط، بمعنى <g>διὰ τοῦτο, ὅτι</g> (باللاتينية <l>propterea quod</l>)، </f> <s><b>لأنّ</b>: <r v=\"Luke.1.13\"></r> <r v=\"Luke.2.7\"></r> <r v=\"Luke.21.28\"></r>، <r v=\"Acts.13.35\"></r> <r v=\"Acts.18.10\"></r> <r v=\"Acts.20.26\"></r> <r v=\"Acts.22.18\"></r>، <r v=\"Rom.1.19\"></r>، <r v=\"Rom.1.21\"></r> <r v=\"Rom.3.20\"></r> <r v=\"Rom.8.7\"></r>، <r v=\"Rom.8.21\"></r>، <r v=\"1Cor.15.9\"></r>، <r v=\"Phil.2.26\"></r>، <r v=\"1Thess.2.8\"></r>، <r v=\"1Thess.2.18\"></r> <r v=\"1Thess.4.6\"></r>، <r v=\"Heb.11.5\"></r>، <r v=\"Heb.11.23\"></r>، <r v=\"Jas.4.3\"></r>، <r v=\"1Pet.1.16\"></r>، <r v=\"1Pet.1.24\"></r> <r v=\"1Pet.2.6\"></r>. وهي عادةً أقوى من <g>ὅτι</g>، لكنها أحيانًا، كما في <r v=\"Luke.1.13\"></r>، <r v=\"Rom.1.19\"></r>، <r v=\"1Thess.2.18\"></r>، تقترب من معناها في اليونانية الحديثة: <b>فإنّ</b>؛ قارن <r v=\"1Thess.2.18\"></r>†</s>","en":"<f><o>δι-ότι </o>, conjunct., for <g>διὰ τοῦτο, ὅτι</g> (Lat. <l>propterea quod</l>), </f> <s><b>because</b>: <r v=\"Luke.1.13\"></r> <r v=\"Luke.2.7\"></r> <r v=\"Luke.21.28\"></r>, <r v=\"Acts.13.35\"></r> <r v=\"Acts.18.10\"></r> <r v=\"Acts.20.26\"></r> <r v=\"Acts.22.18\"></r>, <r v=\"Rom.1.19\"></r>, <r v=\"Rom.1.21\"></r> <r v=\"Rom.3.20\"></r> <r v=\"Rom.8.7\"></r>, <r v=\"Rom.8.21\"></r>, <r v=\"1Cor.15.9\"></r>, <r v=\"Phil.2.26\"></r>, <r v=\"1Thess.2.8\"></r>, <r v=\"1Thess.2.18\"></r> (Lft., <i>Notes</i>, 37) <r v=\"1Thess.4.6\"></r>, <r v=\"Heb.11.5\"></r>, <r v=\"Heb.11.23\"></r>, <r v=\"Jas.4.3\"></r>, <r v=\"1Pet.1.16\"></r>, <r v=\"1Pet.1.24\"></r> <r v=\"1Pet.2.6\"></r>. It is usually stronger than <g>ὅτι</g>, but sometimes, as in <r v=\"Luke.1.13\"></r>, <r v=\"Rom.1.19\"></r>, <r v=\"1Thess.2.18\"></r>, approximates to MGr. sense, <b>for</b>; cf. Milligan, <r v=\"1Thess.2.18\"></r>†</s>"},"G1355":{"l":"διόπερ","o":2,"ar":"<f>** <o>διό-περ </o> أداة ربط (<g>διό</g>، انظره، مقوّاة بـ <g>πέρ</g>)، </f> <s><b>لهذا السبب عينه، لذلك</b>: <r v=\"1Cor.8.13\"></r> <r v=\"1Cor.10.14\"></r>.†</s>","en":"<f>** <o>διό-περ </o> conjunct. (<g>διό</g>, q.v., strengthened by <g>πέρ</g>), </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.8.17\"></r>; II Mac <i>5</i> * ;] </e> </et> <s><b>for which very reason</b>: <r v=\"1Cor.8.13\"></r> <r v=\"1Cor.10.14\"></r>.†</s>"},"G1349":{"l":"δίκη","o":3,"ar":"<f><o>δίκη</o>، <g>-ης, ἡ </g></f> <s n=\"1.\"><b>عادة</b>. </s> <s n=\"2.\"><b>حقّ</b>. </s> <s n=\"3.\"><b>محاكمة قضائية</b>؛ ومن ثمّ نتيجتها: <b>تنفيذ الحكم، عقاب</b>: <g>δ. τίνειν</g>: <r v=\"2Thess.1.9\"></r>؛ <g>δ. υπεχειν</g>: <r v=\"Jude.1.7\"></r>. </s> <s n=\"4.\">مُشخَّصة (قارن اللاتينية <l>Justitia</l>): <b>العدالة، النقمة</b>: <r v=\"Acts.28.4\"></r>.†</s>","en":"<f><o>δίκη</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5359\">נקם</h>, <h n=\"H7378\">ריב</h>, etc. ;]</e> </et> <s n=\"1.\"><b>custom</b>. </s> <s n=\"2.\"><b>right</b>. </s> <s n=\"3.\"><b>a judicial hearing</b>; hence its result, <b>the execution of a sentence, punishment</b>: <g>δ. τίνειν</g>, <r v=\"2Thess.1.9\"></r>; <g>δ. υπεχειν</g>, <r v=\"Jude.1.7\"></r>. </s> <s n=\"4.\">Personified (cf. Lat. <l>Justitia</l>), <b>justice, vengeance</b>: <r v=\"Acts.28.4\"></r>.†</s>"},"G1305":{"l":"διατροφή","o":1,"ar":"<f>** <o>δια-τροφή</o>، <g>ῆς, ἡ</g></f> <s><b>طعام، قوت</b>: <r v=\"1Tim.6.8\"></r>.†</s>","en":"<f>** <o>δια-τροφή</o>, <g>ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διατρέφω</g>, <b>to support, sustain</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.6.49\"></r> * ;] </e> </et> <s><b>food, nourishment</b>: <r v=\"1Tim.6.8\"></r>.†</s>"},"G1388":{"l":"δόλος","o":14,"ar":"<f><o>δόλος</o>، <g>-ου, ὁ</g>، </f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>طُعم</b>. </s> <s n=\"2.\"><b>فخّ</b>. </s> <s n=\"3.\">بالمعنى المجرد: <b>مكر، غشّ</b>: <r v=\"Matt.26.4\"></r>، <r v=\"Mark.7.22\"></r> <r v=\"Mark.14.1\"></r>، <r v=\"John.1.47\"></r>، <r v=\"Acts.13.10\"></r>، <r v=\"Rom.1.29\"></r>، <r v=\"2Cor.12.16\"></r>، <r v=\"1Thess.2.3\"></r>، <r v=\"1Pet.2.1\"></r>، <r v=\"1Pet.2.22\"></r> <r v=\"1Pet.3.10\"></r> <i>(السبعينية)</i> (<g>λαλῆσαι δ.</g>).†</s>","en":"<f><o>δόλος</o>, <g>-ου, ὁ</g>, </f> <et><e t=\"septuagint\">[in LXX chiefly for <h n=\"H4820\">מִרְמָה</h>;]</e></et> <s n=\"1.\">in Hom., <b>a bait</b>. </s> <s n=\"2.\"><b>a snare</b>. </s> <s n=\"3.\">In the abstract, <b>craft, deceit</b>: <r v=\"Matt.26.4\"></r>, <r v=\"Mark.7.22\"></r> <r v=\"Mark.14.1\"></r>, <r v=\"John.1.47\"></r>, <r v=\"Acts.13.10\"></r>, <r v=\"Rom.1.29\"></r>, <r v=\"2Cor.12.16\"></r>, <r v=\"1Thess.2.3\"></r>, <r v=\"1Pet.2.1\"></r>, <r v=\"1Pet.2.22\"></r> <r v=\"1Pet.3.10\"></r> <i>(LXX)</i> (<g>λαλῆσαι δ.</g>).†</s>"},"G1329":{"l":"διερμηνεύω","o":6,"ar":"<f>**† <o>δι-ερμηνεύω </o></f> <s>صيغة مكثَّفة من <g>ἐρμηνεύω</g>، <b>يفسّر</b>؛ </s> <s n=\"(a)\"><b>يشرح، يوضّح</b>: مع المنصوب، <r v=\"Luke.24.27\"></r>؛ مطلقًا، <r v=\"1Cor.12.30\"></r> <r v=\"1Cor.14.5\"></r>، <r v=\"1Cor.14.13\"></r>، <r v=\"1Cor.14.27\"></r>؛ </s> <s n=\"(b)\"><b>يترجم</b>: <r v=\"Acts.9.36\"></r>.†</s>","en":"<f>**† <o>δι-ερμηνεύω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.1.36\"></r> * ;] </e> </et> <s>intensive of <g>ἐρμηνεύω</g>, <b>to interpret</b>; </s> <s n=\"(a)\"><b>to explain, expound</b>: c. acc, <r v=\"Luke.24.27\"></r>; absol., <r v=\"1Cor.12.30\"></r> <r v=\"1Cor.14.5\"></r>, <r v=\"1Cor.14.13\"></r>, <r v=\"1Cor.14.27\"></r>; </s> <s n=\"(b)\"><b>to translate</b>: <r v=\"Acts.9.36\"></r>.†</s>"},"G1362":{"l":"διπλόος","o":4,"ar":"<f><o>διπλόος</o></f> <s><b>مضاعف، مزدوج</b>: <r v=\"1Tim.5.17\"></r>، <r v=\"Rev.18.6\"></r>؛ <g>διπλότιρον</g>، <b>ضعفين</b>: <r v=\"Matt.23.15\"></r>.†</s>","en":"<f><o>διπλόος</o></f> <et> <e t=\"derivation\">(poët., <g>διπλός</g>, whence corp. <g>-ότερον</g>), <g>-όη, -όον</g> (<g>-οῦ, -ῆ, -οῦν</g>) </e> <e t=\"septuagint\">[in LXX for <h n=\"H3717\">כָּפַל</h>, <h n=\"H4932\">מִשְׁנֶה</h>, and cognates ;]</e> </et> <s><b>twofold, double</b>: <r v=\"1Tim.5.17\"></r>, <r v=\"Rev.18.6\"></r>; <g>διπλότιρον</g>, <b>in twofold measure</b>: <r v=\"Matt.23.15\"></r>.†</s>"},"G1347":{"l":"δικαίωσις","o":2,"ar":"<f><o>δικαίωσις</o>، <g>-εως, ἡ</g></f> <s><b>فعل الإعلان عن البر، تبرير، تبرئة</b>: <r v=\"Rom.4.25\"></r> <r v=\"Rom.5.18\"></r>.†</s>","en":"<f><o>δικαίωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>δικαιόω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4941\">מִשְׁפָּט</h>, <r v=\"Lev.24.22\"></r> * ;]</e> </et> <s><b>the act of pronouncing righteous, justification, acquittal</b>: <r v=\"Rom.4.25\"></r> <r v=\"Rom.5.18\"></r> (Cremer, 199).†</s>"},"G1386":{"l":"δόλιος","o":1,"ar":"<f><o>δόλιος</o>، <g>-α, -ον</g></f> <s><b>ماكر، غاشّ</b>: <r v=\"2Cor.11.13\"></r>.†</s>","en":"<f><o>δόλιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δόλος</g>), </e> <e t=\"septuagint\">[in LXX—chiefly in Pss, Pr, Si—for<h n=\"H4820\">מִרִמָה</h>etc.;]</e> </et> <s><b>deceitful</b>: <r v=\"2Cor.11.13\"></r>.†</s>"},"G1345":{"l":"δικαίωμα","o":10,"ar":"<f><o>δικαίωμα</o>، <g>-τος, τ</g></f> <s>تعبير محسوس عن البر، أي تعبير فعل <g>δικαίωσις</g> ونتيجته، «إعلان أن الأمر <g>δίκαιον</g>، أو أن الشخص <g>δίκαιος</g>»، ومن ثمّ: <s n=\"(a)\"><b>فريضة، حكم</b>: <g>δ. τ. θεοῦ</g>، <r v=\"Rom.1.32\"></r>؛ <g>τ. κυρίου</g>، <r v=\"Luke.1.6\"></r>؛ <g>τ. νόμου</g>، <r v=\"Rom.2.26\"></r> <r v=\"Rom.8.4\"></r>؛ <g>λατρείας</g>، <r v=\"Heb.9.1\"></r>؛ <g>σαρκός</g>، <r v=\"Heb.9.10\"></r>؛ </s> <s n=\"(b)\"><b>قضاء، حكم</b>: <b>بالتبرير</b>، <r v=\"Rom.5.16\"></r> (وأيضًا <r v=\"Rom.5.18\"></r>)، أو <b>بالدينونة</b>؛ </s> <s n=\"(c)\"><b>عمل بر</b>: <r v=\"Rom.5.18\"></r>، <r v=\"Rev.15.4\"></r> <r v=\"Rev.19.8\"></r>.†</s></s>","en":"<f><o>δικαίωμα</o>, <g>-τος, τ</g></f> <et> <e t=\"derivation\">(&lt; <g>δικαιόω</g>), </e> <e t=\"septuagint\">[in LXX most freq. for <h n=\"H2706\">חֹק</h>, in Ez, chiefly for <h n=\"H4941\">מִשְׁפָּט</h>, in Pss, <g>τὰ δ.</g>, freq. for <h n=\"H6490\">פּׅקּוּדִים</h> ;] </e> </et> <s>a concrete expression of righteousness, the expression and result of the act of <g>δικαίωσις</g>, \"a declaration that a thing is <g>δίκαιον</g>, or that a person is <g>δίκαιος</g>,\" hence, <s n=\"(a)\"><b>an ordinance</b>: <g>δ. τ. θεοῦ</g>, <r v=\"Rom.1.32\"></r>; <g>τ. κυρίου</g>, <r v=\"Luke.1.6\"></r>; <g>τ. νόμου</g>, <r v=\"Rom.2.26\"></r> <r v=\"Rom.8.4\"></r>; <g>λατρείας</g>, <r v=\"Heb.9.1\"></r>; <g>σαρκός</g>, <r v=\"Heb.9.10\"></r>; </s> <s n=\"(b)\"><b>a sentence</b>: <b>of acquittal</b>, <r v=\"Rom.5.16\"></r> (also <r v=\"Rom.5.18\"></r>; <i>ICC</i>, in l.), or <b>of condemnation</b>; </s> <s n=\"(c)\"><b>a righteous act</b>: <r v=\"Rom.5.18\"></r> (RV), <r v=\"Rev.15.4\"></r> <r v=\"Rev.19.8\"></r> (on the usage of <g>π.</g>, v. MM, <i>Exp.</i>, iii, xi).†</s></s>"},"G1375":{"l":"διωγμός","o":10,"ar":"<f><o>διωγμός</o>، <g>-οῦ, ὁ</g></f> <s><b>اضطهاد</b>: <r v=\"Matt.13.21\"></r>، <r v=\"Mark.4.17\"></r> <r v=\"Mark.10.30\"></r> <r v=\"Acts.8.1\"></r> <r v=\"Acts.13.50\"></r>، <r v=\"Rom.8.35\"></r>، <r v=\"2Cor.12.10\"></r>، <r v=\"2Thess.1.4\"></r>، <r v=\"2Tim.3.11\"></r>.†</s>","en":"<f><o>διωγμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>διώκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.11.19\"></r> (<h n=\"H7291\">רדף</h> pi.), <r v=\"Lam.3.19\"></r> (<h n=\"H4788\">מָרוּד</h>), <r v=\"2Macc.12.23\"></r> * ;] </e> </et> <s><b>persecution</b>: <r v=\"Matt.13.21\"></r>, <r v=\"Mark.4.17\"></r> <r v=\"Mark.10.30\"></r> <r v=\"Acts.8.1\"></r> <r v=\"Acts.13.50\"></r>, <r v=\"Rom.8.35\"></r>, <r v=\"2Cor.12.10\"></r>, <r v=\"2Thess.1.4\"></r>, <r v=\"2Tim.3.11\"></r>.†</s>"},"G1397":{"l":"δουλεία","o":5,"ar":"<f><o>δουλεία</o>، <g>-ας, ἡ</g> </f> <s><b>عبودية</b>: <r v=\"Rom.8.15\"></r>، <r v=\"Rom.8.21\"></r>، <r v=\"Gal.4.24\"></r> <r v=\"Gal.5.1\"></r>، <r v=\"Heb.2.15\"></r>.†</s>","en":"<f><o>δουλεία</o> (T, <g>-λία</g>), <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>δουλεύω</g>), </e> <e t=\"septuagint\">[in LXX, as <r v=\"Exod.13.3\"></r>, for <h n=\"H5650\">עֶבֶד</h> and cognates ;]</e> </et> <s><b>slavery, bondage</b>: <r v=\"Rom.8.15\"></r>, <r v=\"Rom.8.21\"></r>, <r v=\"Gal.4.24\"></r> <r v=\"Gal.5.1\"></r>, <r v=\"Heb.2.15\"></r>.†</s>"},"G1395":{"l":"δότης","o":1,"ar":"<f>† <o>δότης</o>، <g>-ου, ὁ</g></f> <s>= <g>δοτήρ</g>، </s> <s><b>معطٍ</b>: <r v=\"2Cor.9.7\"></r> <i>(السبعينية)</i> (ولا يرد في غيره).†</s>","en":"<f>† <o>δότης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δίδωμι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.22.8\"></r> * ;]</e> </et> <s>= <g>δοτήρ</g>, </s> <s><b>a giver</b>: <r v=\"2Cor.9.7\"></r> <i>(LXX)</i> (not elsewhere).†</s>"},"G1396":{"l":"δουλαγωγέω","o":1,"ar":"<f>*† <o>δουλαγωγέω</o>، <g>-ῶ</g></f> <s><b>استعبد، أخضع للعبودية</b>: <r v=\"1Cor.9.27\"></r>.†</s>","en":"<f>*† <o>δουλαγωγέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δοῦλος</g>, <g>ἄγω</g>), </e> </et> <s><b>to make a slave, bring into bondage</b>: <r v=\"1Cor.9.27\"></r> (Cremer, 703).†</s>"},"G1373":{"l":"δίψος","o":1,"ar":"<f><o>δίψος</o>، <g>-εος (-ους), τό </g> </f> <s><b>عطش</b>: <r v=\"2Cor.11.27\"></r>.†</s>","en":"<f><o>δίψος</o>, <g>-εος (-ους), τό </g></f> <et> <e t=\"derivation\">(late form of <g>δίψα</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6770\">צָמֵא</h> and cognates ;] </e> </et> <s><b>thirst</b>: <r v=\"2Cor.11.27\"></r>.†</s>"},"G1302":{"l":"διατί","o":0,"ar":"<f><o>δια-τί </o>، في النص المستلَم بدلاً من <g>διὰ τί</g>، انظر تحت مدخل <x><g>διά</g></x>. </f>","en":"<f><o>δια-τί </o>, T, Rec. for <g>διὰ τί</g>, v.s. <x><g>διά</g></x>. </f>"},"G1380":{"l":"δοκέω","o":62,"ar":"<f><o>δοκέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>يظن، يحسب</b>: <r v=\"Matt.24.44\"></r>، <r v=\"Luke.12.40\"></r>، <r v=\"Heb.10.29\"></r>؛ مع المصدر، <r v=\"Matt.3.9\"></r>، <r v=\"Luke.8.18\"></r>، <r v=\"Luke.24.37\"></r>، <r v=\"John.5.39\"></r>، <r v=\"John.16.2\"></r>، <r v=\"Acts.12.9\"></r>، <r v=\"Acts.27.13\"></r>، <r v=\"1Cor.3.18\"></r>، <r v=\"1Cor.7.40\"></r>، <r v=\"1Cor.8.2\"></r>، <r v=\"1Cor.10.12\"></r>، <r v=\"1Cor.14.37\"></r>، <r v=\"Gal.6.3\"></r>، <r v=\"Phil.3.4\"></r>، <r v=\"Jas.1.26\"></r>؛ مع المنصوب والمصدر، <r v=\"1Cor.12.23\"></r>، <r v=\"2Cor.11.16\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Matt.6.7\"></r>، <r v=\"Matt.26.53\"></r>، <r v=\"Mark.6.49\"></r>، <r v=\"Luke.12.51\"></r>، <r v=\"Luke.13.2\"></r>، <r v=\"Luke.13.4\"></r>، <r v=\"Luke.19.11\"></r>، <r v=\"John.5.45\"></r>، <r v=\"John.11.13\"></r>، <r v=\"John.11.31\"></r>، <r v=\"John.13.29\"></r>، <r v=\"John.20.15\"></r>، <r v=\"1Cor.4.9\"></r>، <r v=\"2Cor.12.19\"></r>، <r v=\"Jas.4.5\"></r>. </s> <s n=\"2.\"><b>يبدو، يُعتبَر</b>: <r v=\"Acts.25.27\"></r>؛ مع المصدر، <r v=\"Mark.10.42\"></r>، <r v=\"Luke.10.36\"></r>، <r v=\"Luke.22.24\"></r>، <r v=\"Acts.17.13\"></r>، <r v=\"Acts.26.9\"></r>، <r v=\"1Cor.11.16\"></r>، <r v=\"1Cor.12.22\"></r>، <r v=\"2Cor.10.9\"></r>، <r v=\"Gal.2.6\"></r>، <r v=\"Gal.2.9\"></r>، <r v=\"Heb.4.1\"></r>، <r v=\"Heb.12.11\"></r>؛ <g>οἱ δοκοῦντες</g>، <b>المعتبرون</b>، <r v=\"Gal.2.2\"></r>. وبصيغة غير شخصية: يبدو، مع القابل للشخص؛ </s> <s n=\"(a)\"><b>يرى، يظن</b>: <r v=\"Matt.17.25\"></r>، <r v=\"Matt.18.12\"></r>، <r v=\"Matt.21.28\"></r>، <r v=\"Matt.22.17\"></r>، <r v=\"Matt.22.42\"></r>، <r v=\"Matt.26.66\"></r>، <r v=\"John.11.56\"></r>، <r v=\"Heb.12.10\"></r>؛ </s> <s n=\"(b)\"><b>يَحسُن لدى، يُستحسَن</b>: مع المصدر، <r v=\"Luke.1.3\"></r>، <r v=\"Acts.15.22\"></r>، <r v=\"Acts.15.25\"></r>، <r v=\"Acts.15.23\"></r>، <r v=\"Acts.15.34\"></r>.†</s>","en":"<f><o>δοκέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δόκος</g>, <b>opinion</b>, &lt; <g>δέκομαι</g>, Ion, form of <g>δέχ-</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H2895\">טוֹב</h>, <h n=\"H5068\">נָדַב</h>, etc. ;]</e> </et> <s n=\"1.\"><b>to be of opinion, suppose</b>: <r v=\"Matt.24.44\"></r>, <r v=\"Luke.12.40\"></r>, <r v=\"Heb.10.29\"></r>; c. inf., <r v=\"Matt.3.9\"></r>, <r v=\"Luke.8.18\"></r> <r v=\"Luke.24.37\"></r>, <r v=\"John.5.39\"></r> <r v=\"John.16.2\"></r>, <r v=\"Acts.12.9\"></r> <r v=\"Acts.27.13\"></r>, <r v=\"1Cor.3.18\"></r> <r v=\"1Cor.7.40\"></r> <r v=\"1Cor.8.2\"></r> <r v=\"1Cor.10.12\"></r> <r v=\"1Cor.14.37\"></r>, <r v=\"Gal.6.3\"></r>, <r v=\"Phil.3.4\"></r>, <r v=\"Jas.1.26\"></r>; c. acc et inf., <r v=\"1Cor.12.23\"></r>, <r v=\"2Cor.11.16\"></r>; seq. <g>ὅτι</g>, <r v=\"Matt.6.7\"></r> <r v=\"Matt.26.53\"></r>, <r v=\"Mark.6.49\"></r>, <r v=\"Luke.12.51\"></r> <r v=\"Luke.13.2\"></r>, <r v=\"Luke.13.4\"></r> <r v=\"Luke.19.11\"></r>, <r v=\"John.5.45\"></r> <r v=\"John.11.13\"></r>, <r v=\"John.11.31\"></r> <r v=\"John.13.29\"></r> <r v=\"John.20.15\"></r>, <r v=\"1Cor.4.9\"></r>, <r v=\"2Cor.12.19\"></r>, <r v=\"Jas.4.5\"></r>. </s> <s n=\"2.\"><b>to seem, be reputed</b>: <r v=\"Acts.25.27\"></r>; c. inf., <r v=\"Mark.10.42\"></r>, <r v=\"Luke.10.36\"></r> <r v=\"Luke.22.24\"></r>, <r v=\"Acts.17.13\"></r> <r v=\"Acts.26.9\"></r>, <r v=\"1Cor.11.16\"></r> <r v=\"1Cor.12.22\"></r>, <r v=\"2Cor.10.9\"></r>, <r v=\"Gal.2.6\"></r>, <r v=\"Gal.2.9\"></r>, <r v=\"Heb.4.1\"></r> <r v=\"Heb.12.11\"></r>; <g>οἱ δοκοῦντες</g>, <b>those of repute</b>, <r v=\"Gal.2.2\"></r>. Impers., it seems, c. dat. pers.; </s> <s n=\"(a)\"><b>to think</b>: <r v=\"Matt.17.25\"></r> <r v=\"Matt.18.12\"></r> <r v=\"Matt.21.28\"></r> <r v=\"Matt.22.17\"></r>, <r v=\"Matt.22.42\"></r> <r v=\"Matt.26.66\"></r>, <r v=\"John.11.56\"></r>, <r v=\"Heb.12.10\"></r>; </s> <s n=\"(b)\"><b>to please, seem good to</b>: c. inf., <r v=\"Luke.1.3\"></r>, <r v=\"Acts.15.22\"></r>, <r v=\"Acts.15.25\"></r>, <r v=\"Acts.15.23\"></r>, <r v=\"Acts.15.34\"></r>.†</s> <sy><i>SYN.</i> <e t=\"derivation\">(<g>δοκέω</g> 1.): <g>ἡγέομαι</g> <i>2</i>, <g>νομίζω</g><i>2</i>, <g>οἴομαι</g>; <g>ἡ.</g> and <g>ν.</g> properly express belief resting on external proof, <g>ἡ.</g> denoting the more careful judgment; <g>δ.</g> and <g>οἴ.</g> imply a subjective judgment which in the case of <g>οἴ.</g> is based on feeling, in <g>δ.</g> on thought (v. Schmidt, c. 17) </e></sy> <sy><e t=\"derivation\">(<g>δοκέω</g> 2.): <g>φαίνομαι</g>; <g>φ.</g>, from the standpoint of the object, \"expresses how a matter phenomenally shows and presents itself\"; <g>δ.</g>, from the standpoint of the observer, expresses one's subjective judgment about a matter (v. Tr., <i>Syn.</i>, § lxxx; Cremer, 204).</e></sy>"},"G1330":{"l":"διέρχομαι","o":43,"ar":"<f><o>δι-έρχομαι </o></f> <s n=\"1.\"><b>يجتاز، يعبر</b>؛ </s> <s n=\"(a)\">عن الأشياء: <r v=\"Matt.19.24\"></r>، <r v=\"Mark.10.25\"></r>، <r v=\"Luke.2.35\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">عن الأشخاص: <r v=\"Luke.19.4\"></r>؛ مع المنصوب للمكان، <r v=\"Luke.19.1\"></r>، <r v=\"Heb.4.14\"></r>، <r v=\"Acts.12.10\"></r>؛ يليه <g>διά</g> مع المضاف إليه للمكان، <r v=\"Matt.12.43\"></r>، <r v=\"1Cor.10.1\"></r>؛ يليه <g>εἰς</g>، <r v=\"Mark.4.35\"></r>؛ <g>ἕως</g>، <r v=\"Luke.2.15\"></r>. </s> <s n=\"2.\"><b>يجول</b>: <r v=\"Luke.9.6\"></r>، <r v=\"Acts.20.25\"></r>؛ وعن خبر، <b>يذيع، ينتشر</b>، <r v=\"Luke.5.15\"></r>. </s>","en":"<f><o>δι-έρχομαι </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H83\">אבר</h>, <h n=\"H1980\">הלךְ</h>, <h n=\"H935\">בּוֹא</h>, etc. ;]</e> </et> <s n=\"1.\"><b>to go through, pass through</b>; </s> <s n=\"(a)\">of things: <r v=\"Matt.19.24\"></r>, <r v=\"Mark.10.25\"></r>, <r v=\"Luke.2.35\"></r>, al.; </s> <s n=\"(b)\">of persons: <r v=\"Luke.19.4\"></r>; c. acc loc., <r v=\"Luke.19.1\"></r>, <r v=\"Heb.4.14\"></r>, <r v=\"Acts.12.10\"></r>; seq. <g>διά</g>, c. gen. loc., <r v=\"Matt.12.43\"></r>, <r v=\"1Cor.10.1\"></r>; seq. <g>εἰς</g>, <r v=\"Mark.4.35\"></r>; <g>ἕως</g>, <r v=\"Luke.2.15\"></r>. </s> <s n=\"2.\"><b>to go about</b>: <r v=\"Luke.9.6\"></r>, <r v=\"Acts.20.25\"></r>; of a report, <b>to spread, go abroad</b> (Thuc.), <r v=\"Luke.5.15\"></r>. </s>"},"G1317":{"l":"διδακτικός","o":2,"ar":"<f><o>διδακτικός</o>، <g>-ή, -όν</g></f> <s><b>صالح للتعليم</b>: <r v=\"1Tim.3.2\"></r>، <r v=\"2Tim.2.24\"></r>.†</s>","en":"<f><o>διδακτικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(= cl. <g>διδασκαλικός</g>) </e> </et> <s><b>apt at teaching</b>: <r v=\"1Tim.3.2\"></r>, <r v=\"2Tim.2.24\"></r>.†</s>"},"G1376":{"l":"διώκτης","o":1,"ar":"<f>*† <o>διώκτης</o>، <g>-ου, ὁ</g></f> <s><b>مضطهِد</b>: <r v=\"1Tim.1.13\"></r>.†</s>","en":"<f>*† <o>διώκτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>διώκω</g>), </e> </et> <s><b>a persecutor</b>: <r v=\"1Tim.1.13\"></r>.†</s>"},"G1377":{"l":"διώκω","o":45,"ar":"<f><o>διώκω </o></f> <s n=\"1.\"><b>يطرد، يُهرِب</b>: <r v=\"Matt.23.34\"></r>. </s> <s n=\"2.\"><b>يتبع، يلاحق</b>؛ </s> <s n=\"(a)\">عن الأشخاص؛ مع المنصوب، دون عداوة: <b>يتبع، يسعى وراء</b>: <r v=\"Luke.17.23\"></r>؛ وبقصد عدائي: <r v=\"Acts.26.11\"></r>، <r v=\"Rev.12.13\"></r>. ومن ثمّ <b>يضطهد</b>: <r v=\"Matt.5.10-Matt.5.12\"></r>، <r v=\"Matt.5.44\"></r> <r v=\"Matt.10.23\"></r>، <r v=\"Luke.11.49\"></r> <r v=\"Luke.21.12\"></r>، <r v=\"John.5.16\"></r> <r v=\"John.15.20\"></r>، <r v=\"Acts.7.52\"></r> <r v=\"Acts.9.4\"></r>، <r v=\"Acts.9.5\"></r> <r v=\"Acts.22.4\"></r>، <r v=\"Acts.22.7\"></r>، <r v=\"Acts.22.8\"></r> <r v=\"Acts.26.14\"></r>، <r v=\"Acts.26.15\"></r>، <r v=\"Rom.12.14\"></r>، <r v=\"1Cor.4.12\"></r> <r v=\"1Cor.15.9\"></r>، <r v=\"2Cor.4.9\"></r>، <r v=\"Gal.1.13\"></r>، <r v=\"Gal.1.23\"></r> <r v=\"Gal.4.29\"></r> <r v=\"Gal.5.11\"></r> <r v=\"Gal.6.12\"></r>، <r v=\"Phil.3.6\"></r>، <r v=\"2Tim.3.12\"></r>؛ </s> <s n=\"(b)\">مجازيًا، مع المنصوب للشيء، عن السعي الحثيث وراء أمر: <r v=\"Rom.9.30\"></r>، <r v=\"1Tim.6.11\"></r>، <r v=\"2Tim.2.22\"></r>؛ <g>νόμον δικαιοσύνης</g>، <r v=\"Rom.9.31\"></r>؛ <g>τ. φιλοξενίαν</g>، <r v=\"Rom.12.13\"></r>؛ <g>εἰρήνην</g>، <r v=\"Heb.12.14\"></r>، <r v=\"1Pet.3.11\"></r>؛ <g>τὰ τῆς εἰ.</g>، <r v=\"Rom.14.19\"></r>؛ <g>τ. ἀγάπην</g>، <r v=\"1Cor.14.1\"></r>؛ <g>τὸ ἀγαθόν</g>، <r v=\"1Thess.5.15\"></r>؛ مطلقًا: <b>يمضي قُدُمًا، يندفع</b> أو <b>يُسرع</b>، <r v=\"Phil.3.12\"></r>، <r v=\"Phil.3.14\"></r>.†</s>","en":"<f><o>διώκω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7291\">רדף</h> ;] </e> </et> <s n=\"1.\"><b>to put to flight, drive away</b>: <r v=\"Matt.23.34\"></r>. </s> <s n=\"2.\"><b>to pursue</b>; </s> <s n=\"(a)\">of persons; c. acc, without hostility, <b>to follow after</b>: <r v=\"Luke.17.23\"></r>; with hostile purpose: <r v=\"Acts.26.11\"></r>, <r v=\"Rev.12.13\"></r>. Hence, <b>to persecute</b>: <r v=\"Matt.5.10-Matt.5.12\"></r>, <r v=\"Matt.5.44\"></r> <r v=\"Matt.10.23\"></r>, <r v=\"Luke.11.49\"></r> <r v=\"Luke.21.12\"></r>, <r v=\"John.5.16\"></r> <r v=\"John.15.20\"></r>, <r v=\"Acts.7.52\"></r> <r v=\"Acts.9.4\"></r>, <r v=\"Acts.9.5\"></r> <r v=\"Acts.22.4\"></r>, <r v=\"Acts.22.7\"></r>, <r v=\"Acts.22.8\"></r> <r v=\"Acts.26.14\"></r>, <r v=\"Acts.26.15\"></r>, <r v=\"Rom.12.14\"></r>, <r v=\"1Cor.4.12\"></r> <r v=\"1Cor.15.9\"></r>, <r v=\"2Cor.4.9\"></r>, <r v=\"Gal.1.13\"></r>, <r v=\"Gal.1.23\"></r> <r v=\"Gal.4.29\"></r> <r v=\"Gal.5.11\"></r> <r v=\"Gal.6.12\"></r>, <r v=\"Phil.3.6\"></r>, <r v=\"2Tim.3.12\"></r>; </s> <s n=\"(b)\">metaph., c. acc rei, of seeking eagerly after: <r v=\"Rom.9.30\"></r>, <r v=\"1Tim.6.11\"></r>, <r v=\"2Tim.2.22\"></r>; <g>νόμον δικαιοσύνης</g>, <r v=\"Rom.9.31\"></r>; <g>τ. φιλοξενίαν</g>, <r v=\"Rom.12.13\"></r>; <g>εἰρήνην</g>, <r v=\"Heb.12.14\"></r>, <r v=\"1Pet.3.11\"></r>; <g>τὰ τῆς εἰ.</g>, <r v=\"Rom.14.19\"></r>; <g>τ. ἀγάπην</g>, <r v=\"1Cor.14.1\"></r>; <g>τὸ ἀγαθόν</g>, <r v=\"1Thess.5.15\"></r>; absol., <b>to follow on, drive</b>, or <b>speed on</b> (Æsch.), <r v=\"Phil.3.12\"></r>, <r v=\"Phil.3.14\"></r>.†</s>"},"G1322":{"l":"διδαχή","o":30,"ar":"<f><o>διδαχή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">بالمعنى الموضوعي: <b>تعليم، عقيدة</b>، أي ما يُعلَّم: <r v=\"Mark.1.27\"></r>، <r v=\"John.7.16\"></r>، <r v=\"Acts.17.19\"></r>، <r v=\"Rom.6.7\"></r> <r v=\"Rom.16.17\"></r>، <r v=\"2John.1.10\"></r>، <r v=\"Rev.2.24\"></r>؛ مع المضاف إليه الدال على الملكية، <r v=\"Matt.7.28\"></r> <r v=\"Matt.16.12\"></r> <r v=\"Matt.22.33\"></r>، <r v=\"Mark.1.22\"></r> <r v=\"Mark.11.18\"></r>، <r v=\"Luke.4.32\"></r>، <r v=\"John.18.19\"></r>، <r v=\"Acts.5.28\"></r>، <r v=\"Rev.2.14\"></r>، <r v=\"Rev.2.15\"></r>؛ <g>ἡ δ.</g>، أي تعليم المسيح، <r v=\"John.7.17\"></r>، <r v=\"Acts.13.12\"></r>، <r v=\"2John.1.9\"></r>؛ قارن <g>τὴν δ.</g>، <r v=\"Titus.1.9\"></r>؛ مع المضاف إليه الدال على المفعول، <g>βαπτισμῶν δ.</g>، <r v=\"Heb.6.2\"></r>؛ في الجمع، <r v=\"Heb.13.9\"></r>. </s> <s n=\"2.\">بالمعنى الفعلي: <b>التعليم</b> (فعل التعليم): <r v=\"Acts.2.42\"></r>، <r v=\"2Tim.4.2\"></r>؛ <g>ἐν τ. δ.</g>، في أثناء تعليمه: <r v=\"Mark.4.2\"></r> <r v=\"Mark.12.38\"></r>؛ <g>λαλεῖν ἐν δ.</g>، <r v=\"1Cor.14.6\"></r>؛ <g>ἔχειν δ.</g>، <r v=\"1Cor.14.26\"></r>.†</s>","en":"<f><o>διδαχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διδάσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.60.1\"></r> (<h n=\"H3925\">למד</h> pi.); Sm.: <r v=\"Deut.33.8\"></r> * ;]</e> </et> <s n=\"1.\">objectively, <b>teaching, doctrine</b>, that which is taught: <r v=\"Mark.1.27\"></r>, <r v=\"John.7.16\"></r>, <r v=\"Acts.17.19\"></r>, <r v=\"Rom.6.7\"></r> <r v=\"Rom.16.17\"></r>, <r v=\"2John.1.10\"></r>, <r v=\"Rev.2.24\"></r>; c. gen. poss., <r v=\"Matt.7.28\"></r> <r v=\"Matt.16.12\"></r> <r v=\"Matt.22.33\"></r>, <r v=\"Mark.1.22\"></r> <r v=\"Mark.11.18\"></r>, <r v=\"Luke.4.32\"></r>, <r v=\"John.18.19\"></r>, <r v=\"Acts.5.28\"></r>, <r v=\"Rev.2.14\"></r>, <r v=\"Rev.2.15\"></r>; <g>ἡ δ.</g>, of Christ, <r v=\"John.7.17\"></r>, <r v=\"Acts.13.12\"></r>, <r v=\"2John.1.9\"></r>; cf. <g>τὴν δ.</g>, <r v=\"Titus.1.9\"></r>; c. gen. obj., <g>βαπτισμῶν δ.</g>, <r v=\"Heb.6.2\"></r>; pl., <r v=\"Heb.13.9\"></r>. </s> <s n=\"2.\">Actively, <b>teaching</b>: <r v=\"Acts.2.42\"></r>, <r v=\"2Tim.4.2\"></r>; <g>ἐν τ. δ.</g>, in the course of his teaching: <r v=\"Mark.4.2\"></r> <r v=\"Mark.12.38\"></r>; <g>λαλεῖν ἐν δ.</g>, <r v=\"1Cor.14.6\"></r>; <g>ἔχειν δ.</g>, <r v=\"1Cor.14.26\"></r> (<i>DCG</i>, i, 485; Cremer, 181).†</s> <sy><i>SYN.</i>: <g>διδασκαλία</g> </sy>"},"G1351":{"l":"δίλογος","o":1,"ar":"<f>*† <o>δίλογος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: بمعنى <g>διλογεῖν, -ία</g>، <b>كثير التكرار</b>. </s> <s n=\"2.\">في العهد الجديد، على الأرجح (قارن <g>δίγλωσσος</g>، <r v=\"Prov.11.13\"></r>، <r v=\"Sir.5.9\"></r>): <b>ذو لسانين</b>: <r v=\"1Tim.3.8\"></r>.†</s>","en":"<f>*† <o>δίλογος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>, <g>λέγω</g>), </e> </et> <s n=\"1.\">in sense of <g>διλογεῖν, -ία</g> (Xen.), <b>given to repetition</b>. </s> <s n=\"2.\">In NT, prob. (cf. <g>δίγλωσσος</g>, <r v=\"Prov.11.13\"></r>, <r v=\"Sir.5.9\"></r>) <b>double-tongued</b>: <r v=\"1Tim.3.8\"></r>.†</s>"},"G1303":{"l":"διατίθημι","o":7,"ar":"<f><o>δια-τίθημι </o></f> <s><b>وضع كلاً على حدة، رتّب، نظّم</b>. وفي العهد الجديد بالصيغة الوسطى فقط؛ </s> <s n=\"1.\"> <s n=\"(a)\">بوجه عام، <b>تصرّف في</b>؛ مع القابل للشخص، <b>عيّن لأحد، جعل له</b>، <r v=\"Luke.22.29\"></r>؛ </s> <s n=\"(b)\"><b>أوصى، كتب وصية</b>: <r v=\"Heb.9.16\"></r>، <r v=\"Heb.9.17\"></r> (لكن انظر تحت مدخل <g>διαθήκη</g>). </s> </s> <s n=\"2.\"><g>δ. διαθήκην</g>، <b>قطع عهدًا</b>: مع القابل للشخص، <r v=\"Heb.8.10\"></r> <i>(السبعينية)</i>؛ يليه <g>πρός</g> مع المنصوب للشخص، <r v=\"Acts.3.25\"></r>، <r v=\"Heb.10.16\"></r> <i>(السبعينية)</i> (قارن <g>ἀντι-διατίθημι</g>).†</s>","en":"<f><o>δια-τίθημι </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3772\">כּרת</h>, freq. <g>δ. διαθήκην</g> (<h n=\"H3772\">כָּרַת בְּרִית</h>) ;] </e> </et> <s><b>to place separately, arrange, dispose</b>. Mid, only in NT; </s> <s n=\"1.\"> <s n=\"(a)\">in general, <b>to dispose of</b>; c. dat. pers., <b>to assign to one</b>, <r v=\"Luke.22.29\"></r>; </s> <s n=\"(b)\"><b>to dispose of by a will, make a testament</b> (in cl., <g>δ. διαθήκην</g> also in this sense): <r v=\"Heb.9.16\"></r>, <r v=\"Heb.9.17\"></r> (but cf. R, mg., and v.s. <g>διαθήκη</g>). </s> </s> <s n=\"2.\"><g>δ. διαθήκην</g>, <b>to make a covenant</b> (Aristoph.): c. dat. pers., <r v=\"Heb.8.10\"></r> <i>(LXX)</i>; seq. <g>πρός</g>, c. acc pers., <r v=\"Acts.3.25\"></r>, <r v=\"Heb.10.16\"></r> <i>(LXX)</i> (cf. <g>ἀντι-διατίθημι</g>).†</s>"},"G1383":{"l":"δοκίμιον","o":2,"ar":"<f><o>δοκίμιον</o>، <g>-ου, τό </g></f> <s>يُعَدّ عادةً صيغة أخرى من <g>δοκιμεῖον</g>، <b>امتحان، اختبار</b>، وربما كذلك في <r v=\"Jas.1.3\"></r>، لكن انظر الكلمة التالية.†</s>","en":"<f><o>δοκίμιον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.17.3\"></r> <r v=\"Prov.27.21\"></r> (<h n=\"H4715\">מַצְרֵף</h>) * ;] </e> </et> <s>usually regarded as a variant form of <g>δοκιμεῖον</g>, <b>a test</b>, and so perh. <r v=\"Jas.1.3\"></r> (v. Mayor, in l.), but see next word (cf. Cremer, 212, 702).†</s>"},"G1361":{"l":"Διοτρέφης","o":1,"ar":"<f><o>Διοτρέφης</o>، <g>-ες</g> </f> <s>اسم علم، <b>ديوتريفس</b>: <r v=\"3John.1.9\"></r>.†</s>","en":"<f><o>Διοτρέφης</o> (Rec. <g>-τρεψής</g>), <g>-ες</g> </f> <et> <e t=\"derivation\">(&lt; <g>Διός</g>, gen. of <g>Ζεύς</g> + <g>τρέφω</g>: <b>cherished by Zeus</b>), </e> </et> <s>as proper name, <b>Diotrephes</b>: <r v=\"3John.1.9\"></r>.†</s>"},"G1336":{"l":"διηνεκής","o":4,"ar":"<f>** <o>δι-ηνεκής</o>، <g>-ές</g></f> <s><b>متواصل، مستمر</b>: ظرفًا، <g>εἰς τὸ δ.</g>، <b>على الدوام</b>، <r v=\"Heb.7.3\"></r> <r v=\"Heb.10.1\"></r>، <r v=\"Heb.10.12\"></r>، <r v=\"Heb.10.14\"></r>.†</s>","en":"<f>** <o>δι-ηνεκής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>διήνεγκα</g>, aor. of <g>διαφέρω</g>) </e> <e t=\"septuagint\">[in Sm.: Ps 47 (48):15, 88 (89):30 ;] </e> </et> <s><b>unbroken, continuous</b>: adverbially, <g>εἰς τὸ δ.</g>, <b>continually</b> (for exx., v. Deiss., <i>BS</i>, 251), <r v=\"Heb.7.3\"></r> <r v=\"Heb.10.1\"></r>, <r v=\"Heb.10.12\"></r>, <r v=\"Heb.10.14\"></r>.†</s>"},"G1334":{"l":"διηγέομαι","o":8,"ar":"<f><o>δι-ηγέομαι</o>، <g>-οῦμαι </g></f> <s><b>روى بالتفصيل، أخبر، وصف</b>: مطلقًا، <r v=\"Heb.11.32\"></r>؛ مع منصوب الشيء، <r v=\"Acts.8.33\"></r>؛ مع القابل للشخص، يليه <g>πῶς</g>، <r v=\"Mark.5.16\"></r>، <r v=\"Acts.9.27\"></r> <r v=\"Acts.12.17\"></r>؛ <g>ἅ εἶδον</g>، <r v=\"Mark.9.9\"></r>؛ <g>ὅσα ἐποίησε, -αν</g>، <r v=\"Luke.8.39\"></r> <r v=\"Luke.9.10\"></r>.†</s>","en":"<f><o>δι-ηγέομαι</o>, <g>-οῦμαι </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5608\">ספר</h> pi. ;] </e> </et> <s><b>to set out in detail, recount, describe</b>: absol., <r v=\"Heb.11.32\"></r>; c. acc rei, <r v=\"Acts.8.33\"></r>; c. dat. pers., seq. <g>πῶς</g>, <r v=\"Mark.5.16\"></r>, <r v=\"Acts.9.27\"></r> <r v=\"Acts.12.17\"></r>; <g>ἅ εἶδον</g>, <r v=\"Mark.9.9\"></r>; <g>ὅσα ἐποίησε, -αν</g>, <r v=\"Luke.8.39\"></r> <r v=\"Luke.9.10\"></r>.†</s>"},"G1366":{"l":"δίστομος","o":3,"ar":"<f><o>δίστομος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: عن الأنهار والطرق، <b>ذو مصبّين، متفرّع إلى فرعين</b>. </s> <s n=\"2.\">عن السيوف، <b>ذو حدّين</b>: <r v=\"Heb.4.12\"></r>، <r v=\"Rev.1.16\"></r> <r v=\"Rev.2.12\"></r>.† </s>","en":"<f><o>δίστομος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>, <g>στόμα</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.3.16\"></r>, <r v=\"Ps.149.6\"></r>, <r v=\"Prov.5.4\"></r> (<h n=\"H6310\">פִּּיּוֹת</h>), <r v=\"Sir.21.3\"></r> * ;]</e> </et> <s n=\"1.\">of rivers and roads, <b>double-mouthed, double branching</b>. </s> <s n=\"2.\">Of swords (Eur.; LXX, ll. c.), <b>two-edged</b>: <r v=\"Heb.4.12\"></r>, <r v=\"Rev.1.16\"></r> <r v=\"Rev.2.12\"></r>.† </s>"},"G1306":{"l":"διαυγάζω","o":1,"ar":"<f>**† <o>δι-αυγάζω </o></f> <s><b>أضاء من خلال، انفجر (النهار)</b>: <r v=\"2Pet.1.19\"></r> (قارن <g>ἕως οὗ διαπνεύσῃ ἡ ἡμέρα</g>، <r v=\"Song.2.17\"></r>).†</s>","en":"<f>**† <o>δι-αυγάζω </o></f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Job.25.5\"></r> * ;] </e> </et> <s><b>to shine through, to dawn</b>: <r v=\"2Pet.1.19\"></r> (cf. <g>ἕως οὗ διαπνεύσῃ ἡ ἡμέρα</g>, <r v=\"Song.2.17\"></r>).†</s>"},"G1374":{"l":"δίψυχος","o":2,"ar":"<f>*† <o>δίψυχος</o>، <g>-ον</g></f> <s><b>ذو رأيين، متردّد</b>: <r v=\"Jas.1.8\"></r> <r v=\"Jas.4.8\"></r>.†</s>","en":"<f>*† <o>δίψυχος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>, <g>ψυχή</g>), </e> </et> <s><b>of two minds, wavering</b>: <r v=\"Jas.1.8\"></r> <r v=\"Jas.4.8\"></r> (Cremer, 588; <i>DB</i>, iv, 528).†</s>"},"G1326":{"l":"διεγείρω","o":6,"ar":"<f>** <o>δι-εγείρω </o></f> <s><b>أيقظ تمامًا، أيقظ</b> كما من الراحة أو النوم: <r v=\"Luke.8.24\"></r>؛ المبني للمجهول، <r v=\"Mark.4.39\"></r>، <r v=\"Luke.8.24\"></r>؛ عن البحر، <r v=\"John.6.18\"></r>. مجازيًا، عن الذهن: <g>ἐν ὑπομνήσει</g>، <r v=\"2Pet.1.13\"></r>، <r v=\"2Pet.3.1\"></r>.†</s>","en":"<f>** <o>δι-εγείρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.1.4\"></r>, <r v=\"Ezra.1.1\"></r>, <r v=\"2Macc.7.21\"></r> <r v=\"2Macc.15.10\"></r>, <r v=\"3Macc.5.15\"></r> * ;]</e> </et> <s><b>to arouse completely, arouse</b> as from rest or sleep: <r v=\"Luke.8.24\"></r>; pass., <r v=\"Mark.4.39\"></r>, <r v=\"Luke.8.24\"></r>; of the sea, <r v=\"John.6.18\"></r>. Metaph., of the mind: <g>ἐν ὑπομνήσει</g>, <r v=\"2Pet.1.13\"></r> <r v=\"2Pet.3.1\"></r>.†</s>"},"G1357":{"l":"διόρθωμα","o":1,"ar":"<f>* <o>διόρθωμα</o>، <g>-τος, τό</g></f> <s><b>إصلاح، تقويم</b>: <r v=\"Acts.24.3\"></r>.†</s>","en":"<f>* <o>διόρθωμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>διορθόω</g>, <b>to make straight, set right</b>), </e> </et> <s><b>a correction, reform</b>: <r v=\"Acts.24.3\"></r>.†</s>"},"G1338":{"l":"διικνέομαι","o":1,"ar":"<f><o>δι-ικνέομαι</o>، <o>-οῦμαι</o>، </f> <s><b>اجتاز، نفذ، خرق</b>: <r v=\"Heb.4.12\"></r>.†</s>","en":"<f><o>δι-ικνέομαι</o> (Rec. <g>διϊκ-</g>), <o>-οῦμαι</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1272\">בּרח</h> hi., <r v=\"Exod.26.28\"></r> * ;] </e> </et> <s><b>to go through, penetrate</b>: <r v=\"Heb.4.12\"></r>.†</s>"},"G1363":{"l":"διπλόω","o":1,"ar":"<f>* <o>διπλόω</o>، <g>-ῶ</g></f> <s><b>ضاعف</b>: <g>δ. τὰ διπλᾶ</g>، <r v=\"Rev.18.6\"></r>.†</s>","en":"<f>* <o>διπλόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>διπλόος</g>), </e> </et> <s><b>to double</b>: <g>δ. τὰ διπλᾶ</g>, <r v=\"Rev.18.6\"></r>.†</s>"},"G1359":{"l":"Διόσκουροι","o":1,"ar":"<f><o>Διόσ-κουροι</o>، <g>-ων, οἱ</g></f> <s><b>الجوزاء (ديوسكوري)</b> (كاستور وبولكس)، ابنا زفس وليدا التوأمان (الترجمة المنقحة: <b>الأخوان التوأمان</b>): <r v=\"Acts.28.11\"></r>.†</s>","en":"<f><o>Διόσ-κουροι</o>, <g>-ων, οἱ</g></f> <et> <e t=\"derivation\">(Ion. and <g>κοινή</g> form of Att., <g>Διόσκοροι</g>; &lt; <g>Διός</g>, gen. of <g>Ζεύς</g> + <g>κόρος</g>, a son), </e> </et> <s><b>the Dioscuri</b> (Castor and Pollux), twin sons of Zeus and Leda (RV, <b>The Twin Brothers</b>): <r v=\"Acts.28.11\"></r>.†</s>"},"G1324":{"l":"Δίδυμος","o":3,"ar":"<f><o>Δίδυμος</o>، <g>-ου, ὁ</g></f> <s><b>ديديموس (التوأم)</b>، لقب الرسول توما: <r v=\"John.11.16\"></r>، <r v=\"John.20.24\"></r>، <r v=\"John.21.2\"></r>.†</s>","en":"<f><o>Δίδυμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(prop. name from <g>δίδυμος, -η, -ον</g>, <b>double</b>, sc. <g>παῖς</g>, <b>twin</b>) </e> </et> <s><b>Didymus</b>, surname of the apostle Thomas: <r v=\"John.11.16\"></r> <r v=\"John.20.24\"></r> <r v=\"John.21.2\"></r>.†</s>"},"G1399":{"l":"δούλη","o":3,"ar":"<f><o>δούλη</o>، <g>ἡ</g>، انظر تحت مدخل <x><g>δοῦλος</g></x>.</f>","en":"<f><o>δούλη</o>, <g>ἡ</g>, v.s. <x><g>δοῦλος</g></x>.</f>"},"G1339":{"l":"διίστημι","o":3,"ar":"<f><o>δι-ίστημι</o></f> <s><b>فصل، فرّق</b>؛ وعن الزمن (أو المكان): <b>ترك فاصلاً، مرّ بينهما</b>: <g>διαστάσης ὥρας μιᾶς</g>، <r v=\"Luke.22.59\"></r>؛ <g>βραχὺ διαστήσαντες</g>، <r v=\"Acts.27.28\"></r>. وفي المبني للمجهول والصيغة الوسطى والماضي البسيط الثاني والتام والماضي الأتم المبني للمعلوم: <b>انفصل، مضى عنهم</b>: <r v=\"Luke.24.51\"></r>.†</s>","en":"<f><o>δι-ίστημι</o></f> <et> <e t=\"derivation\">(Rec. <g>διΐσ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.5.1\"></r> (<h n=\"H2505\">חלק</h> pi.), <r v=\"Prov.17.9\"></r> (<h n=\"H6504\">פּרד</h> hi.), etc. ;]</e> </et> <s><b>to set apart, separate</b>; of time (or space), <b>to make an interval, intervene</b>: <g>διαστάσης ὥρας μιᾶς</g>, <r v=\"Luke.22.59\"></r>; <g>βραχὺ διαστήσαντες</g>, <r v=\"Acts.27.28\"></r>. In pass., mid. and 2 aor., pf. and plpf. act., <b>to part, withdraw</b>: <r v=\"Luke.24.51\"></r>.†</s>"},"G1337":{"l":"διθάλασσος","o":1,"ar":"<f>*† <o>διθάλασσος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>منقسم إلى بحرين</b> (كالبحر الأسود). </s> <s n=\"2.\"><b>فاصل بين بحرين</b>: <g>τόπον δ.</g>، <b>لسان من اليابسة أو شِعب صخري ممتد في البحر</b>: <r v=\"Acts.27.41\"></r>.†</s>","en":"<f>*† <o>διθάλασσος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>δις, θύλασσα</g>); </e> </et> <s n=\"1.\"><b>divided into two seas</b> (as the Euxine, Strab., ii, 5<i>22</i>). </s> <s n=\"2.\"><b>dividing the sea</b>: <g>τόπον δ.</g>, <b>a tongue of land, or reef, running out into the sea</b>: <r v=\"Acts.27.41\"></r>.†</s>"},"G1367":{"l":"δισχίλιοι","o":1,"ar":"<f><o>δισ-χίλιοι</o>، <g>-αι, -α </g></f> <s><b>ألفان</b>: <r v=\"Mark.5.13\"></r>.†</s>","en":"<f><o>δισ-χίλιοι</o>, <g>-αι, -α </g></f> <s><b>two thousand</b>: <r v=\"Mark.5.13\"></r>.†</s>"},"G1309":{"l":"διαφεύγω","o":1,"ar":"<f><o>δια-φεύγω </o></f> <s><b>هرب عبر، نجا</b>: <r v=\"Acts.27.42\"></r>.†</s>","en":"<f><o>δια-φεύγω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Josh.8.22\"></r> (<h n=\"H6412\">פָּלִיט</h>), <r v=\"Josh.10.28\"></r> (<h n=\"H8300\">שָׂרִיד</h>), etc. ;] </e> </et> <s><b>to flee through, escape</b>: <r v=\"Acts.27.42\"></r>.†</s>"},"G1312":{"l":"διαφθορά","o":6,"ar":"<f><o>δια-φθορά</o>، <g>-ᾶς, ἡ</g></f> <s n=\"1.\"><b>هلاك</b>. </s> <s n=\"2.\"><b>فساد</b> (جسدي أو أدبي): عن القبر، <r v=\"Acts.2.27\"></r> <i>(السبعينية)</i>، <r v=\"Acts.2.31\"></r> <r v=\"Acts.13.34-Acts.13.37\"></r>.†</s>","en":"<f><o>δια-φθορά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διαφθείρω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7843\">שׁחת</h>, and cogn. forms ;]</e> </et> <s n=\"1.\"><b>destruction</b>. </s> <s n=\"2.\"><b>corruption</b> (physical or moral): of the grave, <r v=\"Acts.2.27\"></r> <i>(LXX)</i>, <r v=\"Acts.2.31\"></r> <r v=\"Acts.13.34-Acts.13.37\"></r>.†</s>"},"G1368":{"l":"διυλίζω","o":1,"ar":"<f><o>δι-υλίζω</o></f> <s n=\"1.\"><b>يصفّي تمامًا</b> (<r v=\"Amos.6.6\"></r>). </s> <s n=\"2.\">ثم لاحقًا، <b>يصفّي (ليُخرج)</b>: مجازيًا، <r v=\"Matt.23.24\"></r>.†</s>","en":"<f><o>δι-υλίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δια</g>, <g>ὑλίζω</g>, <b>to strain</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Amos.6.6\"></r> * ;] </e> </et> <s n=\"1.\"><b>to strain thoroughly</b> (Archytas; <r v=\"Amos.6.6\"></r>). </s> <s n=\"2.\">Later, <b>to strain out</b>: fig., <r v=\"Matt.23.24\"></r>.†</s>"},"G1385":{"l":"δοκός","o":6,"ar":"<f><o>δοκός</o>، <g>-οῦ, ἡ</g></f> <s><b>خشبة</b> (عارضة من الخشب): <r v=\"Matt.7.3-Matt.7.5\"></r>، <r v=\"Luke.6.41\"></r>، <r v=\"Luke.6.42\"></r>.†</s>","en":"<f><o>δοκός</o>, <g>-οῦ, ἡ</g></f> <et> <e t=\"derivation\">(<g>δέχομαι</g>) </e> <e t=\"septuagint\">[in LXX for <h n=\"H6982\">קֹרָה</h>, etc. ;] </e> </et> <s><b>a beam</b> of timber: <r v=\"Matt.7.3-Matt.7.5\"></r>, <r v=\"Luke.6.41\"></r>, <r v=\"Luke.6.42\"></r> (<i>DCG</i>, i, 176).†</s>"},"G1316":{"l":"διαχωρίζω","o":1,"ar":"<f><o>δια-χωρίζω </o></f> <s><b>يفصل تمامًا</b>. الصيغة الوسطى، <b>ينفصل، يمضي</b>: يليه <g>ἀπό</g> <r v=\"Luke.9.33\"></r>.† </s>","en":"<f><o>δια-χωρίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.1.4\"></r> ff (<h n=\"H914\">בּדל</h> hi.), <r v=\"Gen.13.9\"></r> ff. (<h n=\"H6504\">פּרד</h> ni.), etc. ;] </e> </et> <s><b>to separate entirely</b>. Mid., <b>to separate oneself, depart</b>: seq. <g>ἀπό</g> <r v=\"Luke.9.33\"></r>.† </s>"},"G1314":{"l":"διαφυλάσσω","o":1,"ar":"<f><o>δια-φυλάσσω </o></f> <s><b>يحرس بعناية</b>، <b>يحمي</b>: مع المنصوب، <r v=\"Luke.4.10\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>δια-φυλάσσω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8104\">שׁמר</h> (as <r v=\"Ps.91.11\"></r>) ;] </e> </et> <s><b>to guard carefully</b> (M, <i>Pr.</i>, 116), <b>defend</b>: c. acc, <r v=\"Luke.4.10\"></r> <i>(LXX)</i>.†</s>"},"G1371":{"l":"διχοτομέω","o":2,"ar":"<f><o>διχοτομέω</o>، <g>-ῶ</g></f> <s><b>شطر إلى اثنين، قطع</b>: ربما مجازيًا عن الجلد الشديد (ولكن قارن <r v=\"1Sam.15.33\"></r>، <r v=\"2Sam.12.31\"></r>، <r v=\"Heb.11.37\"></r>)، <r v=\"Matt.24.51\"></r>، <r v=\"Luke.12.46\"></r>.†</s>","en":"<f><o>διχοτομέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>διχοτόμος</g>, &lt; <g>δίχα</g>, <g>τέμνω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.29.17\"></r> (<h n=\"H5408\">נתח</h> pi.) ;]</e> </et> <s><b>to cut in two, cut asunder</b>: perh. metaph. of severe scourging (but v. Meyer on Mt, l.c., and cf. <r v=\"1Sam.15.33\"></r>, <r v=\"2Sam.12.31\"></r>, <r v=\"Heb.11.37\"></r>), <r v=\"Matt.24.51\"></r>, <r v=\"Luke.12.46\"></r>.†</s>"},"G1358":{"l":"διορύσσω","o":4,"ar":"<f><o>δι-ορύσσω </o></f> <s><b>نقب</b>: مع المنصوب، عن نقب البيوت، <r v=\"Matt.24.43\"></r>، <r v=\"Luke.12.39\"></r>؛ مطلقًا، <r v=\"Matt.6.19\"></r>، <r v=\"Matt.6.20\"></r>.†</s>","en":"<f><o>δι-ορύσσω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.24.16\"></r>, <r v=\"Exod.12.5\"></r>, <r v=\"Exod.12.7\"></r>, <r v=\"Exod.12.12\"></r>, (<h n=\"H2864\">חתר</h>) * ;]</e> </et> <s><b>to dig through</b>: c. acc, of house-breaking (as in <g>π.</g>; MM, <i>Exp.</i>, xi), <r v=\"Matt.24.43\"></r>, <r v=\"Luke.12.39\"></r>; absol., <r v=\"Matt.6.19\"></r>, <r v=\"Matt.6.20\"></r>.†</s>"},"G1333":{"l":"διετία","o":2,"ar":"<f>† <o>διετία</o>، <g>-ας, ἡ</g></f> <s><b>مدة سنتين</b>: <r v=\"Acts.24.27\"></r>، <r v=\"Acts.28.30\"></r>.†</s>","en":"<f>† <o>διετία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διετής</g>), </e> <e t=\"septuagint\">[in LXX (Græc. Ven.): <r v=\"Gen.41.1\"></r> <r v=\"Gen.45.5\"></r> * ;] </e> </et> <s><b>the space of two years</b>: <r v=\"Acts.24.27\"></r> <r v=\"Acts.28.30\"></r>.†</s>"},"G1369":{"l":"διχάζω","o":1,"ar":"<f>** <o>διχάζω</o></f> <s><b>قطع إلى نصفين، قسم إلى اثنين</b>؛ مجازيًا، <b>فرّق (جعله على خلاف)</b>: <r v=\"Matt.10.35\"></r>.†</s>","en":"<f>** <o>διχάζω</o></f> <et> <e t=\"derivation\">(<g>δίχα</g>, <b>apart</b>), </e> <e t=\"septuagint\">[in Aq.: <r v=\"Lev.1.17\"></r>, <r v=\"Deut.14.6\"></r> * ;] </e> </et> <s><b>to cut apart, divide in two</b>; metaph., <b>to set at variance</b>: <r v=\"Matt.10.35\"></r>.†</s>"},"G1335":{"l":"διήγησις","o":1,"ar":"<f><o>δι-ήγησις</o>، <g>-εως, ἡ</g></f> <s><b>قصة، رواية</b>: <r v=\"Luke.1.1\"></r>.†</s>","en":"<f><o>δι-ήγησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>διηγέομαι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.7.15\"></r> <h n=\"H4557\">מִסְפָּר</h> <r v=\"Hab.2.6\"></r> (<h n=\"H2420\">חִידָה</h>), freq. in (<r v=\"Sir.6.35\"></r>, al.), <r v=\"2Macc.2.32\"></r> <r v=\"2Macc.6.17\"></r> ;]</e> </et> <s><b>a narrative</b>: <r v=\"Luke.1.1\"></r> (cf. Milligan, <i>NTD</i>, 130).†</s>"},"G1304":{"l":"διατρίβω","o":9,"ar":"<f><o>δια-τρίβω </o></f> <s><b>فرك بشدة، أبلى بالحكّ، أفنى</b>؛ <g>δ. χρόνον, ἡμέρας</g>، <b>قضى وقتًا</b>: <r v=\"Acts.14.3\"></r>، <r v=\"Acts.14.28\"></r> <r v=\"Acts.16.12\"></r> <r v=\"Acts.20.6\"></r> <r v=\"Acts.25.6\"></r>، <r v=\"Acts.25.14\"></r>. لازمًا مع حذف المفعول، <b>قضى وقتًا، مكث، أقام</b>: <r v=\"John.3.22\"></r> <r v=\"John.11.54\"></r> <r v=\"John.15.35\"></r>، <r v=\"Acts.12.19\"></r>.†</s>","en":"<f><o>δια-τρίβω </o></f> <et> <e t=\"septuagint\">[in LXX <r v=\"Lev.14.8\"></r> (<h n=\"H3427\">ישׁב</h>), <r v=\"Jer.35.7\"></r> (<h n=\"H1481\">גּוּר</h>), <r v=\"Tob.11.8\"></r>, <r v=\"Tob.11.12\"></r>, <r v=\"Jdt.10.2\"></r>, <r v=\"2Macc.14.23\"></r> * ;]</e> </et> <s><b>to rub hard, rub away, consume</b>; <g>δ. χρόνον, ἡμέρας</g>, <b>to spend time</b>: <r v=\"Acts.14.3\"></r>, <r v=\"Acts.14.28\"></r> <r v=\"Acts.16.12\"></r> <r v=\"Acts.20.6\"></r> <r v=\"Acts.25.6\"></r>, <r v=\"Acts.25.14\"></r>. Intransitively with ellipse of object (Bl., § 81, 1), <b>to spend time, stay</b>: <r v=\"John.3.22\"></r> <r v=\"John.11.54\"></r> <r v=\"John.15.35\"></r>, <r v=\"Acts.12.19\"></r>.†</s>"},"G1315":{"l":"διαχειρίζω","o":2,"ar":"<f>* <o>δια-χειρίζω</o></f> <s><b>تولّى، أدار، دبّر</b>. الصيغة الوسطى: </s> <s n=\"(a)\">بمعنى المبني للمعلوم؛ </s> <s n=\"(b)\">عند الكتّاب المتأخرين: <b>وضع يده على، قتل</b>: مع المنصوب، <r v=\"Acts.5.30\"></r> <r v=\"Acts.26.21\"></r>.†</s>","en":"<f>* <o>δια-χειρίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>χείρ</g>), </e> </et> <s><b>to have in hand, conduct, manage</b>. Mid. </s> <s n=\"(a)\">= act.; </s> <s n=\"(b)\">in late writers (Polyb., FlJ, al.), <b>to lay hands on, kill</b>: c. acc, <r v=\"Acts.5.30\"></r> <r v=\"Acts.26.21\"></r>.†</s>"},"G1340":{"l":"διισχυρίζομαι","o":2,"ar":"<f>* <o>δι-ισχυρίζομαι</o>، فعل لازم الصيغة الوسطى؛ </f> <s n=\"1.\"><b>استند إلى</b>. </s> <s n=\"2.\"><b>أكّد بثقة</b>: مع اسم الفاعل، <r v=\"Luke.22.59\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.12.15\"></r>.†</s>","en":"<f>* <o>δι-ισχυρίζομαι</o> (T, Rec. <g>διϊσ-</g>), depon.; </f> <s n=\"1.\"><b>to lean upon</b>. </s> <s n=\"2.\"><b>to affirm confidently</b>: c. ptcp., <r v=\"Luke.22.59\"></r>; c. acc. et inf. (Bl., § 70, 3), <r v=\"Acts.12.15\"></r>.†</s>"},"G1356":{"l":"διοπετής","o":1,"ar":"<f>* <o>διοπετής</o> (ويُكتب أيضًا <g>διϊπ-</g>)، <g>-ές</g> </f> <s><b>الساقط من السماء</b>: <g>τὸ δ.</g> (والمقدَّر <g>ἄγαλμα</g>، <b>تمثال، صورة</b>)، <r v=\"Acts.19.35\"></r>.†</s>","en":"<f>* <o>διοπετής</o> (written also <g>διϊπ-</g>), <g>-ές</g> </f> <et> <e t=\"derivation\">(&lt; <g>δῖος</g>, <g>πίπτω</g>, v. Page on Ac, l.c.; <i>DB</i>, i, 605, n., <i>ext.</i>, 112<i>a</i>; Field, <i>Notes</i>, 130 f.), </e> </et> <s><b>fallen from heaven</b> (R, mg.): <g>τὸ δ.</g> (sc. <g>ἄγαλμα</g>, <b>statue, image</b>), <r v=\"Acts.19.35\"></r>.†</s>"},"G1301":{"l":"διατηρέω","o":2,"ar":"<f><o>δια-τηρέω</o>، <g>-ῶ </g></f> <s><b>حفظ بعناية</b>: <r v=\"Luke.2.51\"></r>؛ يليه <g>ἐκ</g>، <r v=\"Acts.15.29\"></r>.†</s>","en":"<f><o>δια-τηρέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8104\">שׁמר</h>, <h n=\"H5341\">נצר</h>, etc.; seq. <g>ἀπό</g> (for <h n=\"H4480\">מִן</h>), as in <r v=\"Ps.12.8\"></r>;] </e> </et> <s><b>to keep carefully</b>: <r v=\"Luke.2.51\"></r>; seq. <g>ἐκ</g>, <r v=\"Acts.15.29\"></r>.†</s>"},"G1348":{"l":"δικαστής","o":2,"ar":"<f><o>δικαστής</o>، <g>-οῦ, ὁ</g></f> <s><b>قاضٍ</b>: <r v=\"Acts.7.27\"></r>، <r v=\"Acts.7.35\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>δικαστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δικάζω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8199\">שֹׁפֵט</h> ;] </e> </et> <s><b>a judge</b>: <r v=\"Acts.7.27\"></r>, <r v=\"Acts.7.35\"></r> <i>(LXX)</i>.†</s> <sy><i>SYN.</i>: <g>κριτής</g>, wh. \"gives prominence to the mental process\" (Thayer). <g>δ.</g> is the forensic term. In Attic law, the <g>δικασταί</g> were jurors, with a <g>κριτής</g> as presiding officer (LS, s.v.; <i>Enc. Brit.</i><i>11</i>, xii, 504 f.).</sy>"},"G1365":{"l":"διστάζω","o":2,"ar":"<f>* <o>διστάζω</o></f> <s><b>شكّ، تردّد</b>: <r v=\"Matt.14.31\"></r> <r v=\"Matt.28.17\"></r>.†</s>","en":"<f>* <o>διστάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>), </e> </et> <s><b>to doubt, hesitate</b>: <r v=\"Matt.14.31\"></r> <r v=\"Matt.28.17\"></r>.†</s> <sy><i>SYN.</i>: <g>ἀπορέω</g>, <g>διαπορέω</g>, <g>διακρίνομαι</g>, <g>μετεωρίζομαι</g> (v. <i>DCG</i>, i, 491).</sy>"},"G1323":{"l":"δίδραχμος","o":2,"ar":"<f>† <o>δίδραχμος</o>، <g>-ον</g></f> <s><b>قيمته درهمان</b>؛ <g>τὸ δ.</g> (أي <g>νόμισμα</g>، <b>عملة</b>)، </s> <s><b>الدرهمان</b>، يعادل تقريبًا <b>نصف الشاقل</b> اليهودي، وهو مقدار جزية الهيكل: <r v=\"Matt.17.24\"></r>.†</s>","en":"<f>† <o>δίδραχμος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>, <g>δραχμή</g>), </e> </et> <s><b>worth two drachmae</b>; <g>τὸ δ.</g> (sc. <g>νόμισμα</g>, <b>coin</b>), </s> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8255\">שֶׁקֶל</h> (<r v=\"Gen.23.15\"></r>, a1.), also for <h n=\"H3701\">כֶּסֶף</h>: <r v=\"Gen.20.16\"></r>, <r v=\"Deut.22.29\"></r> ;]</e> </et> <s><b>a double drachma</b>, nearly equal to the Jewish <b>half-shekel</b>, the amount of the Temple tax: <r v=\"Matt.17.24\"></r> (<i>DB</i>, iii, 428).†</s>"},"G1332":{"l":"διετής","o":1,"ar":"<f>** <o>διετής</o>، <g>-ές</g></f> <s n=\"1.\"><b>دائم سنتين</b>. </s> <s n=\"2.\"><b>ابن سنتين</b>: <g>ἀπὸ δ.</g> (أي <g>παιδός</g>، أو بصيغة المحايد؛ قارن <r v=\"1Chr.27.23\"></r>، <g>ἀπὸ εἰκοσαετοῦς</g>)، <r v=\"Matt.2.16\"></r>.†</s>","en":"<f>** <o>διετής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>δίς</g>, <g>ἔτος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.10.3\"></r> * ;] </e> </et> <s n=\"1.\"><b>lasting two years</b>. </s> <s n=\"2.\"><b>two years old</b>: <g>ἀπὸ δ.</g> (sc. <g>παιδός</g>, or neuter; cf. <r v=\"1Chr.27.23\"></r>, <g>ἀπὸ εἰκοσαετοῦς</g>), <r v=\"Matt.2.16\"></r>.†</s>"},"G1393":{"l":"Δορκάς","o":2,"ar":"<f><o>Δορκάς</o>، <g>-άδος, ἡ</g></f> <s><b>دوركاس (غزالة)</b>، وتُدعى أيضًا <g>Ταβειθά</g>، انظره: <r v=\"Acts.9.36\"></r>، <r v=\"Acts.9.39\"></r>.†</s>","en":"<f><o>Δορκάς</o>, <g>-άδος, ἡ</g></f> <et> <e t=\"derivation\">(<g>δορκάς</g>, <b>a gazelle</b>), </e> </et> <s><b>Dorcas</b>, also called <g>Ταβειθά</g>, q.v.: <r v=\"Acts.9.36\"></r>, <r v=\"Acts.9.39\"></r>.†</s>"},"G1331":{"l":"διερωτάω","o":1,"ar":"<f>* <o>δι-ερωτάω</o>، <g>-ῶ </g></f> <s><b>وجد بالسؤال</b>: مع المنصوب، <r v=\"Acts.10.17\"></r>.†</s>","en":"<f>* <o>δι-ερωτάω</o>, <g>-ῶ </g></f> <s><b>to find by inquiry</b>: c. acc, <r v=\"Acts.10.17\"></r>.†</s>"},"G1354":{"l":"Διονύσιος","o":1,"ar":"<f><o>Διονύσιος</o>، <g>-ου, ὁ </g></f> <s><b>ديونيسيوس</b>، رجل أثيني: <r v=\"Acts.17.34\"></r>.†</s>","en":"<f><o>Διονύσιος</o>, <g>-ου, ὁ </g></f> <s><b>Dionysius</b>, an Athenian: <r v=\"Acts.17.34\"></r>.†</s>"},"G1350":{"l":"δίκτυον","o":12,"ar":"<f><o>δίκτυον</o>، <g>-ον, τό </g></f> <s>لفظ عام لـ<b>الشبكة</b>: <r v=\"Matt.4.20\"></r>، <r v=\"Matt.4.21\"></r>، <r v=\"Mark.1.18\"></r>، <r v=\"Mark.1.19\"></r>، <r v=\"Luke.5.2\"></r>، <r v=\"Luke.5.4-Luke.5.6\"></r>، <r v=\"John.21.6\"></r>، <r v=\"John.21.8\"></r>، <r v=\"John.21.11\"></r>.†</s>","en":"<f><o>δίκτυον</o>, <g>-ον, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7568\">רֶשֶׁת</h>, <h n=\"H7639\">שְׂבָכָה</h> ;] </e> </et> <s>general term for a <b>net</b>: <r v=\"Matt.4.20\"></r>, <r v=\"Matt.4.21\"></r>, <r v=\"Mark.1.18\"></r>, <r v=\"Mark.1.19\"></r>, <r v=\"Luke.5.2\"></r>, <r v=\"Luke.5.4-Luke.5.6\"></r>, <r v=\"John.21.6\"></r>, <r v=\"John.21.8\"></r>, <r v=\"John.21.11\"></r>.†</s> <sy><i>SYN.</i>: <g>ἀμφίβληστρον</g> (q.v.), <g>σαγήνη</g>.</sy>"},"G1310":{"l":"διαφημίζω","o":3,"ar":"<f>*† <o>δια-φημίζω </o></f> <s>عند الكتّاب المتأخرين فقط، <b>أذاع</b>: <g>τ. λόγον</g> (= <h n=\"H1697\">הַדָּבָר</h>، <b>الأمر</b>)، <r v=\"Mark.1.45\"></r>، <r v=\"Matt.28.15\"></r>؛ مع منصوب الشخص، <b>أذاع خبره</b>: <r v=\"Matt.9.31\"></r>.†</s>","en":"<f>*† <o>δια-φημίζω </o></f> <s>in late writers only, <b>to spread abroad</b>: <g>τ. λόγον</g> (= <h n=\"H1697\">הַדָּבָר</h>, <b>the matter</b>), <r v=\"Mark.1.45\"></r>, <r v=\"Matt.28.15\"></r>; c. acc pers., <b>to spread abroad one's fame</b>: <r v=\"Matt.9.31\"></r>.†</s>"},"G1327":{"l":"διέξοδος","o":1,"ar":"<f><o>δι-έξ-οδος</o>، <g>-ου, ἡ </g></f> <s><b>منفذ، مخرج</b>؛ في الجمع، <g>δ. τῶν ὁδῶν</g>، الترجمة المنقحة: <b>مفارق الطرق</b>: <r v=\"Matt.22.9\"></r>.†</s>","en":"<f><o>δι-έξ-οδος</o>, <g>-ου, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8444\">תּוֹצָאָה</h>, as <r v=\"Num.34.4\"></r> <i>ff.</i>, and freq. in Jos;]</e> </et> <s>in <g>π.</g> of the <b>conclusion</b> of a trial (MM, <i>Exp.</i>, xi); <b>a way out through, an outlet</b>; pl., <g>δ. τῶν ὁδῶν</g>, RV, <b>the partings of the highways</b>: <r v=\"Matt.22.9\"></r>.†</s>"},"G1353":{"l":"διοδεύω","o":2,"ar":"<f>† <o>δι-οδεύω</o>، </f> <s n=\"1.\"><b>اجتاز</b>: مع المنصوب، <r v=\"Acts.17.1\"></r> </s> <s n=\"2.\"><b>سار في، تنقّل في</b> (<r v=\"Bar.4.2\"></r>، <r v=\"1Macc.12.32\"></r>، <r v=\"1Macc.12.33\"></r>): <r v=\"Luke.8.1\"></r>.†</s>","en":"<f>† <o>δι-οδεύω</o>, </f> <et><e t=\"septuagint\">[in LXX chiefly for <h n=\"H5674\">עבר</h> ;] </e></et> <s n=\"1.\"><b>to travel through</b>: c. acc., <r v=\"Acts.17.1\"></r> </s> <s n=\"2.\"><b>to travel along</b> (<r v=\"Bar.4.2\"></r>, <r v=\"1Macc.12.32\"></r>, <r v=\"1Macc.12.33\"></r>): <r v=\"Luke.8.1\"></r>.†</s>"}});A.got[13]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});